/** All translations for zizhitongjian ch.025 — Garrett M. Petersen (2026), Composer 2.5 */
export const entries = [
  { zh: "起閼逢攝提格，盡屠維協洽，凡六年。", literal: "From Efeng Shetige through Tuwei Xiehe; six years in all.", idiomatic: "From Efeng Shetige through Tuwei Xiehe—six years in all." },
  { zh: "1春，三月，詔曰：「蓋聞有功不賞，有罪不誅，雖唐、虞不能化天下。", literal: "1. In spring, the third month, an edict said: \"I have heard that if merit goes unrewarded and guilt unpunished, even Tang and Yu could not transform all under Heaven.", idiomatic: "1. In spring, the third month, an edict said: \"I have heard that if merit goes unrewarded and guilt unpunished, even Tang and Yu could not transform the realm." },
  { zh: "今膠東相王成，勞來不怠，流民自佔八萬餘口，治有異等之效。", literal: "Now Wang Cheng, Chancellor of Jiaodong, toils to comfort the people without slackening; displaced commoners of themselves registered more than eighty thousand mouths, and his governance showed effects of extraordinary grade.", idiomatic: "Now Wang Cheng, Chancellor of Jiaodong, toils to comfort the people without slackening; displaced commoners registered of their own accord more than eighty thousand persons, and his governance showed extraordinary results." },
  { zh: "其賜成爵關內侯，秩中二千石。", literal: "Let Cheng be granted the rank of Marquis within the Passes, with emolument of two thousand bushels, middle grade.", idiomatic: "Let Cheng be granted the rank of Marquis within the Passes, with emolument of two thousand bushels, middle grade." },
  { zh: "」未及徵用，會病卒官。", literal: "\" Before he could be summoned to office, he fell ill and died in his post.", idiomatic: "\" Before he could be summoned to office, he fell ill and died in his post." },
  { zh: "後詔使丞相、御史問郡、國上計長史、守丞以政令得失。", literal: "Later an edict sent the chancellor and the imperial secretary to question the chief clerks, governors, and assistant governors of commanderies and kingdoms who presented annual accounts on the gains and losses of government orders.", idiomatic: "Later an edict sent the chancellor and the imperial secretary to question the chief clerks, governors, and assistant governors of commanderies and kingdoms presenting annual accounts on the gains and losses of government policy." },
  { zh: "或對言：「前膠東相成偽自增加以蒙顯賞，是後俗吏多為虛名」-{云}-。", literal: "Some answered, saying: \"The former Chancellor of Jiaodong Cheng falsely inflated his own figures to win conspicuous reward; after that, vulgar officials often made empty reputations\" -{云}-.", idiomatic: "Some answered: \"The former Chancellor of Jiaodong Cheng falsely inflated his own figures to win conspicuous reward; after that, vulgar officials often made empty reputations\" -{云}-." },
  { zh: "----2夏，四月，戊申，立子奭為皇太子，以丙吉為太傅，太中大夫疏廣為少傅。", literal: "----2 In summer, the fourth month, on wushen, Prince Shi was established as heir apparent; Bing Ji was made Grand Tutor and Palace Grandee Shuguang Junior Tutor.", idiomatic: "----2 In summer, the fourth month, on wushen, Prince Shi was established as heir apparent; Bing Ji was made Grand Tutor and Palace Grandee Shuguang Junior Tutor." },
  { zh: "封太子外祖父許廣漢為平恩侯。", literal: "The crown prince's maternal grandfather Xu Guanghan was enfeoffed as Marquis of Ping'en.", idiomatic: "The crown prince's maternal grandfather Xu Guanghan was enfeoffed as Marquis of Ping'en." },
  { zh: "又封霍光兄孫中郎將雲為冠陽侯。", literal: "Huo Guang's brother's grandson, Palace Cadet Yun, was also enfeoffed as Marquis of Guanyang.", idiomatic: "Huo Guang's brother's grandson, Palace Cadet Yun, was also enfeoffed as Marquis of Guanyang." },
  { zh: "霍顯聞立太子，怒恚不食，歐血，曰：「此乃民間時子，安得立！", literal: "Huo Xian heard that the heir was established, grew furious, refused food, and spat blood, saying: \"This is a commoner's child of the streets—how can he be established!", idiomatic: "Huo Xian heard the heir was established, grew furious, refused food, and spat blood, saying, \"This is a commoner's child of the streets—how can he be established!\"" },
  { zh: "即-{后}-有子，反為王邪！", literal: "If the -{后}- had a son, would he not instead be made king!", idiomatic: "If the -{后}- had a son, would he not instead be made king!" },
  { zh: "」復教皇后令毒太子。", literal: "\" She again instructed the empress to have the heir poisoned.", idiomatic: "\" She again instructed the empress to have the heir poisoned." },
  { zh: "皇后數召太子賜食，保、阿輒先嘗之，-{后}-挾毒不得行。", literal: "The empress repeatedly summoned the heir and bestowed food; his nurses and tutors always tasted it first, and the -{后}-'s plot to use poison could not be carried out.", idiomatic: "The empress repeatedly summoned the heir and bestowed food; his nurses and tutors always tasted it first, and the -{后}-'s plot to use poison could not be carried out." },
  { zh: "----3五月，甲申，丞相賢以老病乞骸骨；", literal: "----3 In the fifth month, on jiashen, Chancellor Xian, owing to age and illness, begged to surrender his bones;", idiomatic: "----3 In the fifth month, on jiashen, Chancellor Xian, owing to age and illness, begged to surrender his bones;" },
  { zh: "賜黃金百斤、安車、駟馬，罷就第。", literal: "he was granted a hundred jin of gold, a comfort carriage, and a four-horse team, and dismissed to his residence.", idiomatic: "he was granted a hundred jin of gold, a comfort carriage, and a four-horse team, and dismissed to his residence." },
  { zh: "丞相致仕自賢始。", literal: "A chancellor's retirement from office began with Xian.", idiomatic: "Retirement of a chancellor from office began with Xian." },
  { zh: "----4六月，壬辰，以魏相為丞相。", literal: "----4 In the sixth month, on renchen, Wei Xiang was made chancellor.", idiomatic: "----4 In the sixth month, on renchen, Wei Xiang was made chancellor." },
  { zh: "辛丑，丙吉為御史大夫，疏廣為太子太傅，廣兄子受為少傅。", literal: "On xinchou, Bing Ji became Imperial Secretary, Shuguang became Grand Tutor of the Heir, and Shuguang's elder brother's son Shou became Junior Tutor.", idiomatic: "On xinchou, Bing Ji became Imperial Secretary, Shuguang became Grand Tutor of the Heir, and Shuguang's elder brother's son Shou became Junior Tutor." },
  { zh: "太子外祖父平恩侯許伯，以為太子少，白使其弟中郎將舜監護太子家。", literal: "The heir's maternal grandfather, the Marquis of Ping'en, Lord Xu, thinking the heir young, reported and had his younger brother, Palace Cadet Shun, oversee and guard the heir's household.", idiomatic: "The heir's maternal grandfather, Marquis of Ping'en Lord Xu, thinking the heir young, reported and had his younger brother, Palace Cadet Shun, oversee the heir's household." },
  { zh: "上以問廣，廣對曰：「太子，國儲副君，師友必於天下英俊，不宜獨親外家許氏。", literal: "The emperor questioned Shuguang; Shuguang answered: \"The heir is the state's stored successor and deputy lord; teachers and friends must be chosen from the outstanding men of all under Heaven—it is not fitting to favor only the maternal kin, the Xu clan.", idiomatic: "The emperor questioned Shuguang; Shuguang answered: \"The heir is the state's stored successor and deputy lord; teachers and friends must be chosen from outstanding men across the realm—it is not fitting to favor only the maternal Xu clan.\"" },
  { zh: "且太子自有太傅、少傅，官屬已備，今復使舜護太子家，示陋，非所以廣太子德於天下也。", literal: "Moreover the heir already has Grand Tutor and Junior Tutor; his official staff is complete. Now to send Shun again to guard the heir's household shows narrowness and is not the way to spread the heir's virtue through all under Heaven.", idiomatic: "Moreover the heir already has Grand and Junior Tutors; his staff is complete. To send Shun again to guard the heir's household shows narrowness and is not how to spread the heir's virtue through the realm.\"" },
  { zh: "」上善其言，以語魏相，相免冠謝曰：「此非臣等所能及。", literal: "\" The emperor approved his words and told Wei Xiang; Xiang removed his cap and apologized, saying: \"This is not what your servants could reach.", idiomatic: "\" The emperor approved his words and told Wei Xiang; Xiang removed his cap and apologized: \"This is not what we could reach.\"" },
  { zh: "」廣由是見器重。", literal: "\" Shuguang from this was seen as heavily valued.", idiomatic: "\" Shuguang from this was held in high regard." },
  { zh: "----5京師大雨雹，大行丞東海蕭望之上疏，言大臣任政，一姓專權之所致。", literal: "----5 In the capital region great hail fell; Assistant Director of the Major Line Xiao Wangzhi of Donghai submitted a memorial saying that great ministers holding government and one clan monopolizing power had caused it.", idiomatic: "----5 In the capital region great hail fell; Assistant Director of the Major Line Xiao Wangzhi of Donghai submitted a memorial saying great ministers holding government and one clan monopolizing power had caused it." },
  { zh: "上素聞望之名，拜為謁者。", literal: "The emperor had long heard Wangzhi's name and appointed him Usher.", idiomatic: "The emperor had long heard Wangzhi's name and appointed him Usher." },
  { zh: "時上博延賢俊，民多上書言便宜，輒下望之問狀；", literal: "At that time the emperor broadly sought worthy and outstanding men; the people often submitted memorials on expedient measures, and he would send them down to Wangzhi to examine the facts;", idiomatic: "At that time the emperor broadly sought worthy men; the people often submitted memorials on expedient measures, and he would send them down to Wangzhi to examine the facts;" },
  { zh: "高者請丞相、御史，次者中二千石試事，滿歲以狀聞；", literal: "the highest were referred to chancellor and imperial secretary, the next given trial office at two thousand bushels, middle grade, and after a full year reported on their performance;", idiomatic: "the highest were referred to chancellor and imperial secretary, the next given trial office at two thousand bushels, middle grade, and after a full year reported on their performance;" },
  { zh: "下者報聞，罷。", literal: "the lowest were reported as heard and dismissed.", idiomatic: "the lowest were reported as heard and dismissed." },
  { zh: "所白處奏皆可。", literal: "Wherever he reported and memorialized, all was approved.", idiomatic: "Wherever he reported and memorialized, all was approved." },
  { zh: "----6冬，十月，詔曰：「乃者九月壬申地震，朕甚懼焉。", literal: "----6 In winter, the tenth month, an edict said: \"Recently on renshen in the ninth month there was an earthquake; We are greatly afraid.", idiomatic: "----6 In winter, the tenth month, an edict said: \"Recently on renshen in the ninth month there was an earthquake; We are greatly afraid.\"" },
  { zh: "有能箴朕過失，及賢良方正直言極諫之士，以匡朕之不逮，毋諱有司。", literal: "Those who can admonish Our faults, and worthy and upright men who speak plainly and remonstrate to the utmost, to correct Our shortcomings—let them not fear the responsible offices.", idiomatic: "Those who can admonish Our faults, and worthy and upright men who speak plainly and remonstrate to the utmost, to correct Our shortcomings—let them not fear the responsible offices.\"" },
  { zh: "朕既不德，不能附遠，是以邊境屯戍未息。", literal: "We lack virtue and cannot draw the distant near; therefore border garrisons and frontier defense have not ceased.", idiomatic: "We lack virtue and cannot draw the distant near; therefore border garrisons and frontier defense have not ceased.\"" },
  { zh: "今復飭兵重屯，久勞百姓，非所以綏天下也。", literal: "Now again to order troops and mass garrisons long wearies the hundred clans—it is not the way to pacify all under Heaven.", idiomatic: "Now again to order troops and mass garrisons long wearies the people—it is not how to pacify the realm.\"" },
  { zh: "其罷車騎將軍、右將軍屯兵。", literal: "Let the garrison troops of the General of Chariots and Cavalry and the Right General be dismissed.", idiomatic: "Let the garrison troops of the General of Chariots and Cavalry and the Right General be dismissed.\"" },
  { zh: "」又詔：「池籞未御幸者，假與貧民。", literal: "\" Another edict said: \"Ponds and parks not yet visited by Us—lend them to the poor.", idiomatic: "\" Another edict said: \"Ponds and parks not yet visited by Us—lend them to the poor.\"" },
  { zh: "郡國宮館勿復修治。", literal: "Let commanderies and kingdoms not again repair palace lodges.", idiomatic: "Let commanderies and kingdoms not again repair palace lodges.\"" },
  { zh: "流民還歸者，假公田，貸種食，且勿算事。", literal: "Displaced people who return home—lend them public fields, loan seed and food, and for the time being do not assess their labor obligations.", idiomatic: "Displaced people who return home—lend them public fields, loan seed and food, and for the time being do not assess their labor obligations.\"" },
  { zh: "」----7霍氏驕侈縱橫。", literal: "\" ----7 The Huo clan was arrogant, extravagant, and ran rampant.", idiomatic: "\" ----7 The Huo clan was arrogant, extravagant, and ran rampant." },
  { zh: "太夫人顯，廣治第室，作乘輿輦，加畫，繡絪馮，黃金塗；", literal: "The Grand Lady Xian extensively built mansion chambers, made imperial carriages and palanquins, added painted decoration, embroidered cushions and canopies, and gilding;", idiomatic: "Grand Lady Xian extensively built mansions, made imperial carriages and palanquins, added painted decoration, embroidered cushions and canopies, and gilding;" },
  { zh: "韋絮薦輪，侍婢以五采絲輓顯遊戲第中；", literal: "with rush padding and felt mats on the wheels; serving maids used five-colored silk to draw Xian roaming and sporting within the mansion;", idiomatic: "with rush padding and felt mats on the wheels; serving maids used five-colored silk to draw Xian roaming within the mansion;" },
  { zh: "與監奴馮子都亂。", literal: "she had illicit relations with the overseer slave Feng Zidu.", idiomatic: "she had illicit relations with the overseer slave Feng Zidu." },
  { zh: "而禹、山亦並繕治第宅，走馬馳逐平樂館。", literal: "Yu and Shan also together repaired mansions and galloped horses racing through the Pingle lodges.", idiomatic: "Yu and Shan also repaired mansions and galloped horses racing through the Pingle lodges." },
  { zh: "雲當朝請，數稱病私出，多從賓客，張圍獵黃山苑中，使倉頭奴上朝謁，莫敢譴者。", literal: "Yun should have attended court audiences but repeatedly claimed illness and went out privately with many retainers, spreading nets to hunt in Huangshan Park, sending a granary-head slave to attend court audience in his place—none dared reprove him.", idiomatic: "Yun should have attended court but repeatedly claimed illness and went out privately with many retainers, spreading nets to hunt in Huangshan Park, sending a granary-head slave to attend court in his place—none dared reprove him." },
  { zh: "顯及諸女晝夜出入長信宮殿中，亡期度。", literal: "Xian and the various daughters went in and out of the Changxin Palace day and night without schedule or measure.", idiomatic: "Xian and the various daughters went in and out of Changxin Palace day and night without schedule or measure." },
  { zh: "帝自在民間，聞知霍氏尊盛日久，內不能善。", literal: "The emperor, from when he was among the common people, had heard of the Huo clan's long-standing eminence and inwardly could not approve.", idiomatic: "The emperor, from when he lived among the common people, had heard of the Huo clan's long eminence and inwardly could not approve." },
  { zh: "既躬親朝政，御史大夫魏相給事中。", literal: "Once he personally took charge of court affairs, Imperial Secretary Wei Xiang served within the palace.", idiomatic: "Once he personally took charge of court affairs, Imperial Secretary Wei Xiang served within the palace." },
  { zh: "顯謂禹、雲、山：「女曹不務奉大將軍餘業，今大夫給事中，他人壹間女，能復自救邪！", literal: "Xian said to Yu, Yun, and Shan: \"You do not strive to uphold the Grand General's legacy; now the Grand Secretary serves within the palace—if others drive in one wedge, can you still save yourselves!", idiomatic: "Xian said to Yu, Yun, and Shan: \"You do not strive to uphold the Grand General's legacy; now the Grand Secretary serves within the palace—if others drive in one wedge, can you still save yourselves!\"" },
  { zh: "」後兩家奴爭道，霍氏奴入御史府，欲躢大夫門；", literal: "\" Later two households' slaves disputed the road; a Huo slave entered the Imperial Secretary's office and wished to trample the Grand Secretary's gate;", idiomatic: "\" Later two households' slaves disputed the road; a Huo slave entered the Imperial Secretary's office and wished to trample the Grand Secretary's gate;" },
  { zh: "御史為叩頭謝，乃去。", literal: "the Imperial Secretary knocked his head in apology for them, and they then left.", idiomatic: "the Imperial Secretary knocked his head in apology for them, and they then left." },
  { zh: "人以謂霍氏，顯等始知憂。", literal: "People told the Huo clan, and Xian and the others first knew to worry.", idiomatic: "People told the Huo clan, and Xian and the others first knew to worry." },
  { zh: "會魏大夫為丞相，數燕見言事；", literal: "When Grand Secretary Wei became chancellor, he was repeatedly granted private audiences to speak on affairs;", idiomatic: "When Grand Secretary Wei became chancellor, he was repeatedly granted private audiences to speak on affairs;" },
  { zh: "平恩侯與侍中金安上等徑出入省中。", literal: "the Marquis of Ping'en and Palace Attendant Jin Anshang and others went directly in and out of the inner palace.", idiomatic: "Marquis of Ping'en and Palace Attendant Jin Anshang and others went directly in and out of the inner palace." },
  { zh: "時霍山領尚書，上令吏民得奏封事，不關尚書，群臣進見獨往來，於是霍氏甚惡之。", literal: "At that time Huo Shan headed the Imperial Secretariat; the emperor allowed officials and commoners to submit sealed memorials without routing through the Secretariat, and ministers entering audience came and went alone—thereupon the Huo clan greatly hated this.", idiomatic: "At that time Huo Shan headed the Imperial Secretariat; the emperor allowed officials and commoners to submit sealed memorials without routing through the Secretariat, and ministers entering audience came and went alone—the Huo clan greatly hated this." },
  { zh: "上頗聞霍氏毒殺-{許后}-而未察，乃徙光女婿度遼將軍、未央衛尉、平陵侯范明友為光祿勳，出次婿諸吏、中郎將、羽林監任勝為安定太守。", literal: "The emperor had somewhat heard that the Huo clan poisoned -{許后}- but had not investigated; he then transferred Guang's son-in-law, General Who Crosses the Liao, Commandant of Weiyang, Marquis of Pingling Fan Mingyou to Palace Grandee, and sent out his second son-in-law, Gentleman-of-the-Various-Offices, Palace Cadet, Colonel of the Forest of Feathers Ren Sheng as Governor of Anding.", idiomatic: "The emperor had somewhat heard the Huo clan poisoned -{許后}- but had not investigated; he transferred Guang's son-in-law, General Who Crosses the Liao, Commandant of Weiyang, Marquis of Pingling Fan Mingyou to Palace Grandee, and sent out his second son-in-law, Gentleman-of-the-Various-Offices, Palace Cadet, Colonel of the Forest of Feathers Ren Sheng as Governor of Anding." },
  { zh: "數月，復出光姊婿給事中、光祿大夫張朔為蜀郡太守，群孫婿中郎將王漢為武威太守。", literal: "Within several months he again sent out Guang's elder sister's son-in-law, Attendant Within the Palace, Palace Grandee Zhang Shuo as Governor of Shu commandery, and the clan grandson's son-in-law, Palace Cadet Wang Han as Governor of Wuwei.", idiomatic: "Within several months he again sent out Guang's elder sister's son-in-law, Attendant Within the Palace, Palace Grandee Zhang Shuo as Governor of Shu, and the clan grandson's son-in-law, Palace Cadet Wang Han as Governor of Wuwei." },
  { zh: "頃之，復徙光長女婿長樂衛尉鄧廣漢為少府。", literal: "Shortly after, he again transferred Guang's eldest son-in-law, Commandant of Changle Wei, Deng Guanghan to Director of the Palace Treasury.", idiomatic: "Shortly after, he again transferred Guang's eldest son-in-law, Commandant of Changle Wei, Deng Guanghan to Director of the Palace Treasury." },
  { zh: "戊戌，更以張安世為衛將軍，兩宮衛尉、城門、北軍兵屬焉。", literal: "On wuxu, Zhang Anshi was again made General of the Guard; the commandants of the two palaces, the gate guards, and the Northern Army all were placed under him.", idiomatic: "On wuxu, Zhang Anshi was again made General of the Guard; the commandants of the two palaces, the gate guards, and the Northern Army were all placed under him." },
  { zh: "以霍禹為大司馬，冠小冠，亡印綬；", literal: "Huo Yu was made Grand Marshal, wearing the small cap, without seal and ribbon;", idiomatic: "Huo Yu was made Grand Marshal, wearing the small cap, without seal and ribbon;" },
  { zh: "罷其屯兵官屬，特使禹官名與光俱大司馬者。", literal: "his garrison troops and official staff were dismissed, and Yu alone was specially left with the same office title as Guang had held, Grand Marshal.", idiomatic: "his garrison troops and official staff were dismissed, and Yu alone was specially left with the same office title Guang had held, Grand Marshal." },
  { zh: "又收范明友度遼將軍印綬，但為光祿勳；", literal: "Fan Mingyou's seal and ribbon as General Who Crosses the Liao were again taken back; he served only as Palace Grandee;", idiomatic: "Fan Mingyou's seal and ribbon as General Who Crosses the Liao were taken back; he served only as Palace Grandee;" },
  { zh: "及光中女婿趙平為散騎、騎都尉、光祿大夫，將屯兵，又收平騎都尉印綬。", literal: "and Guang's middle son-in-law Zhao Ping, Colonel of Loose Riders, Commandant of Cavalry, Palace Grandee, who commanded garrison troops, again had his Commandant of Cavalry seal and ribbon taken back.", idiomatic: "and Guang's middle son-in-law Zhao Ping, Colonel of Loose Riders, Commandant of Cavalry, Palace Grandee, who commanded garrison troops, again had his Commandant of Cavalry seal and ribbon taken back." },
  { zh: "諸領胡、越騎、羽林及兩宮衛將屯兵，悉易以所親信許、史子弟代之。", literal: "All who headed the Hu and Yue cavalry, the Forest of Feathers, and the guard generals' garrison troops of the two palaces were entirely replaced with trusted Xu and Shi clan younger kinsmen.", idiomatic: "All who headed the Hu and Yue cavalry, the Forest of Feathers, and the guard generals' garrison troops of the two palaces were replaced with trusted Xu and Shi clan younger kinsmen." },
  { zh: "----8初，孝武之世，徵發煩數，百姓貧耗，窮民犯法，奸軌不勝，於是使張湯、趙禹之屬，條定法令，作見知故縱、監臨部主之法，緩深、故之罪，急縱、出之誅。", literal: "----8 In the beginning, in the age of Emperor Wu of Filial Piety, levies and summons were frequent and troublesome; the hundred clans grew poor and depleted; the destitute violated the law and wicked paths could not be mastered. Thereupon Zhang Tang, Zhao Yu, and their sort were sent to itemize and fix laws and statutes, making the laws on witnessing knowledge yet conniving release and on supervising and arriving as department heads—relaxing penalties for deep and old offenses, hastening punishments for conniving release.", idiomatic: "----8 In the beginning, in the age of Emperor Wu, levies and summons were frequent; the people grew poor; the destitute violated the law and wicked paths could not be mastered. Zhang Tang, Zhao Yu, and their sort were sent to itemize laws and statutes, making laws on witnessing knowledge yet conniving release and on supervising and arriving as department heads—relaxing penalties for deep and old offenses, hastening punishments for conniving release." },
  { zh: "其後奸猾巧法轉相比況，禁罔浸密，律令煩苛，文書盈於-{几}-閣，典者不能遍睹。", literal: "Afterward the crafty and slippery twisted the law in mutual comparison; prohibitions and nets grew ever denser, statutes and ordinances vexatious and harsh, documents overflowing the -{几}- cabinets so that those in charge could not view them all.", idiomatic: "Afterward the crafty twisted the law in mutual comparison; prohibitions grew ever denser, statutes vexatious and harsh, documents overflowing the -{几}- cabinets so those in charge could not view them all." },
  { zh: "是以郡國承用者駁，或罪同而論異，奸吏因緣為市，所欲活則傅生議，所欲陷則予死比，議者咸冤傷之。", literal: "Therefore what commanderies and kingdoms applied was inconsistent; sometimes the crime was the same but the judgment differed. Wicked officials used the opportunity as a market—whom they wished to spare they clothed with living arguments; whom they wished to trap they gave death analogies. All who discussed it alike grieved at the injustice.", idiomatic: "Therefore what commanderies and kingdoms applied was inconsistent; sometimes the crime was the same but the judgment differed. Wicked officials used the opportunity as a market—whom they wished to spare they clothed with living arguments; whom they wished to trap they gave death analogies. All who discussed it grieved at the injustice." },
  { zh: "廷尉史鉅鹿路溫舒上書曰：「臣聞齊有無知之禍而桓公以興，晉有驪姬之難而文公用伯。", literal: "Clerk of the Commandant of Justice Lu Wenshu of Julu submitted a memorial, saying: \"Your servant has heard that Qi had the calamity of Wuzhi yet Duke Huan thereby rose; Jin had the trouble of Lady Li yet Duke Wen thereby used hegemony.", idiomatic: "Clerk of the Commandant of Justice Lu Wenshu of Julu submitted a memorial: \"Your servant has heard that Qi had the calamity of Wuzhi yet Duke Huan thereby rose; Jin had the trouble of Lady Li yet Duke Wen thereby achieved hegemony.\"" },
  { zh: "近世趙王不終，諸呂作亂，而孝文為太宗。", literal: "In recent times the Prince of Zhao did not reach his end, the Lü clan made rebellion, yet Emperor Wen of Filial Piety became the Grand Ancestor.", idiomatic: "In recent times the Prince of Zhao did not reach his end, the Lü clan rebelled, yet Emperor Wen became the Grand Ancestor.\"" },
  { zh: "繇是觀之，禍亂之作，將以開聖人也。", literal: "From this to observe, the making of calamity and disorder is about to open the way for a sage.", idiomatic: "From this one sees that calamity and disorder are made to open the way for a sage.\"" },
  { zh: "夫繼變亂之後，必有異舊之恩，此賢聖所以昭天命也。", literal: "After inheriting change and disorder there must be favor unlike the old—this is how the worthy and sage display Heaven's mandate.", idiomatic: "After inheriting change and disorder there must be favor unlike the old—this is how the worthy and sage display Heaven's mandate.\"" },
  { zh: "往者昭帝即世無嗣，昌邑淫亂，乃皇天所以開至聖也。", literal: "Formerly Emperor Zhao departed the world without an heir; Changyi was dissolute and disorderly—this was how August Heaven opened the way for the utmost sage.", idiomatic: "Formerly Emperor Zhao died without an heir; Changyi was dissolute and disorderly—this was how August Heaven opened the way for the utmost sage.\"" },
  { zh: "臣聞《春秋》正即位、大一統而慎始也。", literal: "Your servant has heard that the Spring and Autumn Annals rectifies accession, unifies in the great, and is careful at the beginning.", idiomatic: "Your servant has heard that the Spring and Autumn Annals rectifies accession, unifies in the great, and is careful at the beginning.\"" },
  { zh: "陛下初登至尊，與天合符，宜改前世之失，正始受命之統，滌煩文，除民疾，以應天意。", literal: "Your Majesty has newly ascended the utmost honor and matches Heaven's talisman; you ought to change the former age's errors, rectify the beginning of receiving the mandate's succession, wash away vexatious documents, and remove the people's afflictions to respond to Heaven's intent.", idiomatic: "Your Majesty has newly ascended the throne and matches Heaven's talisman; you ought to change the former age's errors, rectify the beginning of receiving the mandate, wash away vexatious documents, and remove the people's afflictions to respond to Heaven's intent.\"" },
  { zh: "臣聞秦有十失，其一尚存，治獄之吏是也。", literal: "Your servant has heard that Qin had ten failures; one still remains—the officers who govern prisons.", idiomatic: "Your servant has heard that Qin had ten failures; one still remains—the officers who govern prisons.\"" },
  { zh: "夫獄者，天下之大命也，死者不可復生，絕者不可復屬。", literal: "For prisons are the great mandate of all under Heaven; the dead cannot live again, the severed cannot be rejoined.", idiomatic: "For prisons are the great mandate of the realm; the dead cannot live again, the severed cannot be rejoined.\"" },
  { zh: "《書》曰：『與其殺不辜，寧失不經。", literal: "The Documents says: \"Rather than execute the innocent, better to miss and not hit the mark.", idiomatic: "The Documents says: \"Rather than execute the innocent, better to miss and not hit the mark.\"" },
  { zh: "』今治獄吏則不然，上下相驅，以刻為明，深者獲公名，平者多後患，故治獄之吏皆欲人死，非憎人也，自安之道在人之死。", literal: "\" Now officers who govern prisons are not so; above and below drive one another, taking harshness as clarity. The deep win public renown; the fair mostly suffer later trouble—therefore prison officers all wish men dead. It is not that they hate people; their path to security lies in men's death.", idiomatic: "\" Now prison officers are not so; above and below drive one another, taking harshness as clarity. The harsh win public renown; the fair mostly suffer later trouble—therefore prison officers all wish men dead. It is not that they hate people; their path to security lies in men's death.\"" },
  { zh: "是以死人之血流離於市，被刑之徒，比肩而立，大辟之計，歲以萬數。", literal: "Therefore dead men's blood flows and pools in the markets; those bearing punishment stand shoulder to shoulder; reckonings of capital punishment number tens of thousands each year.", idiomatic: "Therefore dead men's blood pools in the markets; those bearing punishment stand shoulder to shoulder; capital sentences number in the tens of thousands each year.\"" },
  { zh: "此仁聖之所以傷也，太平之未洽，凡以此也。", literal: "This is what benevolence and sagehood grieve; that great peace is not yet thorough—all for this reason.", idiomatic: "This is what benevolence and sagehood grieve; that great peace is not yet thorough—all for this reason.\"" },
  { zh: "夫人情，安則樂生，痛則思死，棰楚之下，何求而不得！", literal: "For human feeling: when at ease one delights in life; when in pain one thinks of death. Under rod and cudgel, what could one seek and not obtain!", idiomatic: "Human nature: when at ease one delights in life; when in pain one thinks of death. Under rod and cudgel, what could one seek and not obtain!\"" },
  { zh: "故囚人不勝痛，則飾辭以示之；", literal: "Therefore when a prisoner cannot bear the pain, he adorns his words to show them;", idiomatic: "Therefore when a prisoner cannot bear the pain, he adorns his words to show them;" },
  { zh: "吏治者利其然，則指導以明之；", literal: "the officer who governs the case profits from this and guides him to make it clear;", idiomatic: "the officer who governs the case profits from this and guides him to make it clear;" },
  { zh: "上奏畏卻，則鍛練而周內之。", literal: "fearing rejection when memorializing upward, he forges and refines and wraps it tightly within.", idiomatic: "fearing rejection when memorializing upward, he forges and refines and wraps it tightly within." },
  { zh: "蓋奏當之成，雖皋陶聽之，猶以為死有餘辜。", literal: "When a memorial on the sentence is complete, even if Gao Yao heard it, he would still think death left surplus guilt.", idiomatic: "When a memorial on the sentence is complete, even if Gao Yao heard it, he would still think death left surplus guilt." },
  { zh: "何則？", literal: "Why?", idiomatic: "Why?" },
  { zh: "成練者眾，文致之罪明也。", literal: "Because those forged and refined are many, and the crime woven in words is clear.", idiomatic: "Because those forged and refined are many, and the crime woven in words is clear." },
  { zh: "故俗語曰：『畫地為獄，議不入；", literal: "Therefore a common saying runs: \"Draw the ground as a prison—argument will not enter;", idiomatic: "Therefore a common saying runs: \"Draw the ground as a prison—argument will not enter;\"" },
  { zh: "刻木為吏，期不對。", literal: "carve wood as an officer—one would not answer even on appointment.", idiomatic: "carve wood as an officer—one would not answer even on appointment.\"" },
  { zh: "』此皆疾吏之風，悲痛之辭也。", literal: "\" These are all the wind of hateful officers, words of grief and pain.", idiomatic: "\" These are all the wind of hateful officers, words of grief and pain.\"" },
  { zh: "唯陛下省法制，寬刑罰，則太平之風可興於世。", literal: "Only if Your Majesty examines the legal system and relaxes punishments can the wind of great peace rise in the age.", idiomatic: "Only if Your Majesty examines the legal system and relaxes punishments can the wind of great peace rise in the age.\"" },
  { zh: "」上善其言。", literal: "\" The emperor approved his words.", idiomatic: "\" The emperor approved his words." },
  { zh: "----9十二月，詔曰：「間者吏用法巧文浸深，是朕之不德也。", literal: "----9 In the twelfth month, an edict said: \"Recently officers applying the law with crafty documents have grown ever deeper—this is Our lack of virtue.", idiomatic: "----9 In the twelfth month, an edict said: \"Recently officers applying the law with crafty documents have grown ever deeper—this is Our lack of virtue.\"" },
  { zh: "夫決獄不當，使有罪興邪，不辜蒙戮，父子悲恨，朕甚傷之！", literal: "When deciding prison cases is not correct, it makes the guilty rise in wickedness and the innocent suffer execution—fathers and sons grieve and resent; We are deeply grieved!", idiomatic: "When deciding prison cases is not correct, it makes the guilty rise in wickedness and the innocent suffer execution—fathers and sons grieve and resent; We are deeply grieved!\"" },
  { zh: "今遣廷史與郡鞠獄，任輕祿薄，其為置廷尉平，秩六百石，員四人。", literal: "Now We send Court Clerks with commanderies to try prison cases; their duties are light and emoluments thin—let there be established Commandant of Justice Assessors, rank six hundred bushels, four posts.", idiomatic: "Now We send Court Clerks with commanderies to try prison cases; their duties are light and emoluments thin—let Commandant of Justice Assessors be established, rank six hundred bushels, four posts.\"" },
  { zh: "其務平之，以稱朕意！", literal: "Let them strive for fairness to match Our intent!", idiomatic: "Let them strive for fairness to match Our intent!\"" },
  { zh: "」於是每季秋後請讞時，上常幸宣室，齋居而決事，獄刑號為平矣。", literal: "\" Thereupon each time after the autumn quarter when cases for review were submitted, the emperor often favored the Xuan Chamber, dwelt in fasting seclusion to decide affairs, and prison punishments were styled as fair.", idiomatic: "\" Thereupon each autumn quarter when cases for review were submitted, the emperor often visited the Xuan Chamber, dwelt in fasting seclusion to decide affairs, and prison punishments were styled as fair." },
  { zh: "涿郡太守鄭昌上疏言：「今明主躬垂明聽，雖不置廷平，獄將自正；", literal: "Governor of Zhuo commandery Zheng Chang submitted a memorial, saying: \"Now the enlightened lord personally bends his clear hearing; though Assessors are not established, prisons will of themselves be rectified;", idiomatic: "Governor of Zhuo Zheng Chang submitted a memorial: \"Now the enlightened lord personally bends his clear hearing; though Assessors are not established, prisons will of themselves be rectified;\"" },
  { zh: "若開後嗣，不若刪定律令。", literal: "if one opens this for later successors, better to delete and fix laws and statutes.", idiomatic: "if one opens this for later successors, better to delete and fix laws and statutes.\"" },
  { zh: "律令一定，愚民知所避，奸吏無所弄矣。", literal: "Once laws and statutes are fixed, foolish commoners know what to avoid and wicked officials have nothing to manipulate.", idiomatic: "Once laws and statutes are fixed, foolish commoners know what to avoid and wicked officials have nothing to manipulate.\"" },
  { zh: "今不正其本，而置廷平以理其末，政衰聽怠，則廷平將召權而為亂首矣。", literal: "Now if one does not rectify the root but establishes Assessors to manage the branch, when government declines and hearing grows slack, Assessors will summon power and become leaders of disorder.", idiomatic: "Now if one does not rectify the root but establishes Assessors to manage the branch, when government declines and hearing grows slack, Assessors will summon power and become leaders of disorder.\"" },
  { zh: "」----10昭帝時，匈奴使四千騎田車師。", literal: "\" ----10 In Emperor Zhao's time, the Xiongnu sent four thousand horsemen to farm in Cheshi.", idiomatic: "\" ----10 In Emperor Zhao's reign, the Xiongnu sent four thousand horsemen to farm in Cheshi." },
  { zh: "及五將軍擊匈奴，車師田者驚去，車師復通於漢；", literal: "When the Five Generals attacked the Xiongnu, those farming in Cheshi fled in alarm; Cheshi reopened relations with Han;", idiomatic: "When the Five Generals attacked the Xiongnu, the Cheshi farmers fled in alarm, and Cheshi reopened relations with Han;" },
  { zh: "匈奴怒，召其太子軍宿，欲以為質。", literal: "the Xiongnu were angry, summoned their heir Jun Su, and wished to take him as hostage.", idiomatic: "the Xiongnu were angry, summoned their heir Jun Su, and wished to take him as hostage." },
  { zh: "軍宿，焉耆外孫，不欲質匈奴，亡走焉耆，車師王更立子烏貴為太子。", literal: "Jun Su, a grandson by the female line of Yanqi, did not wish to be a hostage to the Xiongnu, fled to Yanqi, and the King of Cheshi established his son Wu Gui as heir.", idiomatic: "Jun Su, a maternal grandson of Yanqi, refused to be a hostage to the Xiongnu, fled to Yanqi, and the King of Cheshi made his son Wu Gui heir instead." },
  { zh: "及烏貴立為王，與匈奴結婚姻，教匈奴遮漢道通烏孫者。", literal: "When Wu Gui was established as king, he formed a marriage alliance with the Xiongnu and taught the Xiongnu to block Han routes to Wusun.", idiomatic: "When Wu Gui became king, he allied with the Xiongnu by marriage and taught them to block Han routes to Wusun." },
  { zh: "是歲，侍郎會稽鄭吉與校尉司馬憙，將免刑罪人田渠犁，積穀，發城郭諸國兵萬餘人與所將田士千五百人共擊車師，破之；", literal: "That year, Gentleman Attendant Zheng Ji of Kuaiji and Commandant Si Ma Xi led convicts exempted from punishment to farm at Queli, accumulated grain, mobilized more than ten thousand troops from the walled-city states together with the fifteen hundred farming soldiers they led to jointly attack Cheshi and defeated them;", idiomatic: "That year, Gentleman Attendant Zheng Ji of Kuaiji and Commandant Si Ma Xi led convicts farming at Queli, accumulated grain, and with more than ten thousand troops from the frontier states plus the fifteen hundred farming soldiers they led jointly attacked Cheshi and defeated them;" },
  { zh: "車師王請降。", literal: "The King of Cheshi requested surrender.", idiomatic: "The King of Cheshi asked to surrender." },
  { zh: "匈奴發兵攻車師；", literal: "The Xiongnu dispatched troops to attack Cheshi;", idiomatic: "The Xiongnu sent troops to attack Cheshi;" },
  { zh: "吉、憙引兵北逢之，匈奴不敢前。", literal: "Ji and Xi led troops north, encountered them, and the Xiongnu did not dare advance.", idiomatic: "Ji and Xi led troops north, met them, and the Xiongnu did not dare advance." },
  { zh: "吉、憙即留一候與卒二十人留守王，吉等引兵歸渠犁。", literal: "Ji and Xi immediately left one scout with twenty soldiers to guard the king; Ji and the rest led troops back to Queli.", idiomatic: "Ji and Xi left one scout with twenty soldiers to guard the king and led the rest back to Queli." },
  { zh: "車師王恐匈奴兵復至而見殺也，乃輕騎奔烏孫。", literal: "The King of Cheshi feared Xiongnu troops would come again and he would be killed, so with light cavalry he fled to Wusun.", idiomatic: "The King of Cheshi, fearing the Xiongnu would return and kill him, fled on light cavalry to Wusun." },
  { zh: "吉即迎其妻子，傳送長安。", literal: "Ji immediately welcomed his wife and children and sent them on to Chang'an.", idiomatic: "Ji welcomed his wife and children and sent them on to Chang'an." },
  { zh: "匈奴更以車師王昆弟兜莫為車師王，收其餘民東徙，不敢居故地；", literal: "The Xiongnu again installed the King's younger brother Dou Mo as King of Cheshi, gathered the remaining people and moved east, and did not dare dwell in the former territory;", idiomatic: "The Xiongnu installed the king's younger brother Dou Mo as King of Cheshi, gathered the remaining people and moved east, and did not dare remain in the old territory;" },
  { zh: "而鄭吉始使吏卒三百人往田車師地以實之。", literal: "while Zheng Ji for the first time sent three hundred clerks and soldiers to farm Cheshi territory to fill it.", idiomatic: "while Zheng Ji for the first time sent three hundred clerks and soldiers to farm Cheshi territory and settle it." },
  { zh: "----11上自初即位，數遣使者求外家；", literal: "----11 Since he first took the throne, the emperor repeatedly sent envoys to seek his maternal kin;", idiomatic: "----11 From the time he first took the throne, the emperor repeatedly sent envoys to seek his maternal kin;" },
  { zh: "久遠，多似類而非是。", literal: "After long years, many resembled them but were not.", idiomatic: "After so long, many who resembled them proved not to be kin." },
  { zh: "是歲，求得外祖母王媼及媼男無故、武。", literal: "That year he found his maternal grandmother Old Lady Wang and her sons Wugu and Wu.", idiomatic: "That year he found his maternal grandmother Old Lady Wang and her sons Wugu and Wu." },
  { zh: "上賜無故、武爵關內侯。", literal: "The emperor bestowed on Wugu and Wu the rank Marquis within the Passes.", idiomatic: "The emperor bestowed on Wugu and Wu the rank of Marquis within the Passes." },
  { zh: "旬月間，賞賜以巨萬計。", literal: "Within a month rewards tallied in the tens of thousands.", idiomatic: "Within a month rewards totaled in the tens of thousands." },
  { zh: "1春，二月，賜外祖母號為博平君；", literal: "1 Spring, second month, he bestowed on his maternal grandmother the title Lady Bo Ping;", idiomatic: "1 In spring, the second month, he bestowed on his maternal grandmother the title Lady Bo Ping;" },
  { zh: "封舅無故為平昌侯，武為樂昌侯。", literal: "he enfeoffed his maternal uncle Wugu as Marquis of Pingchang and Wu as Marquis of Lechang.", idiomatic: "he enfeoffed his maternal uncle Wugu as Marquis of Pingchang and Wu as Marquis of Lechang." },
  { zh: "----2夏，五月，山陽、濟陰雹如雞子，深二尺五寸，殺二十餘人，飛鳥皆死。", literal: "----2 Summer, fifth month, in Shanyang and Jiyin hail like chicken eggs, two chi five cun deep, killed more than twenty people, and flying birds all died.", idiomatic: "----2 In summer, the fifth month, hail like chicken eggs fell in Shanyang and Jiyin to a depth of two chi five cun, killing more than twenty people; all flying birds died." },
  { zh: "----3詔：「自今子有匿父母、妻匿夫、孫匿大父母，皆勿治。", literal: "----3 Edict: \"From now on, if sons conceal parents, wives conceal husbands, or grandsons conceal grandparents, all shall not be prosecuted.", idiomatic: "----3 Edict: \"From now on, if sons conceal parents, wives conceal husbands, or grandsons conceal grandparents, none shall be prosecuted." },
  { zh: "」----4立廣川惠王孫文為廣川王。", literal: "\" ----4 He established Wen, grandson of King Hui of Guangchuan, as King of Guangchuan.", idiomatic: "\" ----4 He established Wen, grandson of King Hui of Guangchuan, as King of Guangchuan." },
  { zh: "----5霍顯及禹、山、雲自見日侵削，數相對啼泣自怨。", literal: "----5 Huo Xian and Yu, Shan, and Yun, seeing themselves daily eroded, repeatedly faced each other weeping and blaming themselves.", idiomatic: "----5 Huo Xian and Yu, Shan, and Yun, seeing their power daily eroded, repeatedly faced each other weeping and blaming themselves." },
  { zh: "山曰：「今丞相用事，縣官信之，盡變易大將軍時法令，發揚大將軍過失。", literal: "Shan said: \"Now the chancellor holds power and the court trusts him; he has completely altered all laws and regulations from the Grand General's time and publicized the Grand General's faults.", idiomatic: "Shan said, \"Now the chancellor holds power and the court trusts him; he has completely overturned the Grand General's laws and publicized the Grand General's faults." },
  { zh: "又，諸儒生多窶人子，遠客饑寒，喜妄說狂言，不避忌諱，大將軍常讎之。", literal: "Also, many Confucian scholars are sons of poor men, far-traveling guests hungry and cold, who delight in reckless wild speech and do not avoid taboo—the Grand General constantly resented them.", idiomatic: "Also, many Confucian scholars are poor men's sons, far-traveling guests hungry and cold, who delight in reckless speech and ignore taboo—the Grand General always resented them." },
  { zh: "今陛下好與諸儒生語，人人自書對事，多言我家者。", literal: "Now Your Majesty delights in speaking with the Confucian scholars; each man writes his own reply on affairs, and many speak of my house.", idiomatic: "Now Your Majesty delights in speaking with Confucian scholars; each writes his own reply on affairs, and many speak of our house." },
  { zh: "嘗有上書言我家昆弟驕恣，其言絕痛；", literal: "Once there was a memorial saying our brothers were arrogant and wanton—the words were utterly harsh;", idiomatic: "Once a memorial said our brothers were arrogant and wanton—the words were utterly harsh;" },
  { zh: "山屏不奏。", literal: "Shan screened it and did not memorialize.", idiomatic: "Shan suppressed it and did not submit it." },
  { zh: "後上書者益黠，盡奏封事，輒使中書令出取之，不關尚書，益不信人。", literal: "Later memorializers grew craftier; all submitted sealed reports, and the emperor would have the Director of the Palace Secretariat fetch them, not passing through the Directors of Writing, trusting people less and less.", idiomatic: "Later memorializers grew craftier; all submitted sealed reports, and the emperor had the Director of the Palace Secretariat fetch them without passing through the Directors of Writing, trusting people less and less." },
  { zh: "又聞民間讙言『霍氏毒殺許皇后』，寧有是邪？", literal: "I also heard among the people rejoicing speech, 'The Huo clan poisoned and murdered Empress Xu'—could there be such a thing?", idiomatic: "I also heard among the people the cry, 'The Huo clan poisoned Empress Xu'—could there be such a thing?" },
  { zh: "」顯恐急，即具以實告禹、山、雲。", literal: "\" Xian in fear and haste immediately told the full truth to Yu, Shan, and Yun.", idiomatic: "\" Xian in fear and haste immediately told Yu, Shan, and Yun the full truth." },
  { zh: "禹、山、雲驚曰：「如是，何不早告禹等！", literal: "Yu, Shan, and Yun in alarm said: \"If so, why did you not tell us earlier!", idiomatic: "Yu, Shan, and Yun cried in alarm, \"If so, why did you not tell us earlier!" },
  { zh: "縣官離散、斥逐諸婿，用是故也。", literal: "The court dismissing and expelling all the sons-in-law—this was the reason.", idiomatic: "The court's dismissal and expulsion of all the sons-in-law—that was the reason." },
  { zh: "此大事，誅罰不小，奈何？", literal: "This is a great matter; the punishment will not be small—what is to be done?", idiomatic: "This is a grave matter; the punishment will be severe—what can we do?" },
  { zh: "」於是始有邪謀矣。", literal: "\" Thereupon they first had wicked plotting.", idiomatic: "\" Thereupon they first turned to wicked plotting." },
  { zh: "雲舅李竟民善張赦，見雲家卒卒，謂竟曰：「今丞相與平恩侯用事，可令太夫人言太后，先誅此兩人。", literal: "Yun's maternal uncle Li Jing, a commoner skilled with Zhang She, seeing the Yun household in sudden distress, said to Jing: \"Now the chancellor and Marquis of Ping'en hold power—you can have the Grand Lady speak to the Empress Dowager and first execute these two men.", idiomatic: "Yun's maternal uncle Li Jing, a commoner friendly with Zhang She, seeing the Yun household in sudden distress, said to Jing, \"Now the chancellor and Marquis of Ping'en hold power—have the Grand Lady speak to the Empress Dowager and first execute these two men." },
  { zh: "移徙陛下，在太后耳。", literal: "Removing and relocating Your Majesty rests with the Empress Dowager alone.", idiomatic: "Removing the emperor rests with the Empress Dowager alone." },
  { zh: "」長安男子張章告之，事下廷尉、執金吾，捕張赦等。", literal: "\" A man of Chang'an named Zhang Zhang reported it; the matter was sent down to the Commandant of Justice and Commandant of the Capital Guard to arrest Zhang She and the rest.", idiomatic: "\" A Chang'an man named Zhang Zhang reported it; the matter went to the Commandant of Justice and Commandant of the Capital Guard to arrest Zhang She and the rest." },
  { zh: "後有詔，止勿捕。", literal: "Later there was an edict ordering them to stop and not arrest.", idiomatic: "Later an edict ordered them to stop and not arrest." },
  { zh: "山等愈恐，相謂曰：「此縣官重太后，故不竟也。", literal: "Shan and the rest grew more fearful and said to each other: \"The court esteems the Empress Dowager, therefore it did not carry through.", idiomatic: "Shan and the rest grew more fearful and said to each other, \"The court esteems the Empress Dowager, so it did not carry through." },
  { zh: "然惡端已見，久之猶發，發即族矣，不如先也。", literal: "Yet the evil root is already visible; if after long it still breaks out, when it breaks out the clan will be exterminated—better to strike first.", idiomatic: "Yet the evil is already visible; if it breaks out later, the whole clan will be exterminated—better to strike first." },
  { zh: "」遂令諸女各歸報其夫，皆曰：「安所相避！", literal: "\" Thereupon they ordered each daughter to return and report to her husband; all said: \"Where is there mutual avoidance!", idiomatic: "\" Thereupon they ordered each daughter to return and report to her husband; all said, \"Where is there any avoiding one another!" },
  { zh: "會李竟坐與諸侯王交通，辭語及霍氏，有詔：「雲、山不宜宿衛，免就第。", literal: "Just then Li Jing was convicted of communicating with kings and princes of feudatory states; his testimony touched the Huo clan. There was an edict: \"Yun and Shan are unfit for palace guard duty; dismissed to their estates.", idiomatic: "Just then Li Jing was convicted of communicating with feudatory kings; his testimony implicated the Huo clan. An edict said, \"Yun and Shan are unfit for palace guard duty; dismissed to their estates." },
  { zh: "」山陽太守張敞上封事曰：「臣聞公子季友有功於魯，趙衰有功於晉，田完有功於齊，皆疇其庸，延及子孫。", literal: "\" Governor of Shanyang Zhang Chang submitted a sealed memorial, saying: \"Your servant has heard that Duke Ji You of Lu, Zhao Cui of Jin, and Tian Wan of Qi all had merit for their states, and each was rewarded for his service, extending to their descendants.", idiomatic: "\" Governor of Shanyang Zhang Chang submitted a sealed memorial, saying, \"Your servant has heard that Ji You of Lu, Zhao Cui of Jin, and Tian Wan of Qi all had merit for their states, were rewarded for their service, and their rewards extended to their descendants." },
  { zh: "終後田氏篡齊，趙氏分晉，季氏顓魯。", literal: "In the end afterward the house of Tian usurped Qi, the house of Zhao partitioned Jin, and the house of Ji dominated Lu.", idiomatic: "In the end the house of Tian usurped Qi, the house of Zhao partitioned Jin, and the house of Ji dominated Lu." },
  { zh: "故仲尼作《春秋》，跡盛衰，譏世卿最甚。", literal: "Therefore Confucius composed the Spring and Autumn Annals, tracing rise and decline, reproaching hereditary ministers most severely.", idiomatic: "Therefore Confucius composed the Spring and Autumn Annals, tracing rise and decline and reproaching hereditary ministers most severely." },
  { zh: "乃者大將軍決大計，安宗廟，定天下，功亦不細矣。", literal: "Recently the Grand General decided great plans, secured the ancestral temple, and settled all under Heaven—his merit is not slight.", idiomatic: "Recently the Grand General decided great plans, secured the ancestral temple, and settled the realm—his merit is not slight." },
  { zh: "夫周公七年耳，而大將軍二十歲，海內之命斷於掌握。", literal: "The Duke of Zhou held power seven years, whereas the Grand General held it twenty years, and the realm's commands rested in his grasp.", idiomatic: "The Duke of Zhou held power seven years, whereas the Grand General held it twenty years, and the realm's commands rested in his grasp." },
  { zh: "方其隆盛時，感動天地，侵迫陰陽。", literal: "At the height of his grandeur he moved Heaven and Earth and encroached upon yin and yang.", idiomatic: "At the height of his power he moved Heaven and Earth and encroached upon yin and yang." },
  { zh: "朝臣宜有明言曰：『陛下褒寵故大將軍以報功德足矣。", literal: "Court ministers ought to have spoken plainly, saying: 'Your Majesty's favor and reward of the former Grand General to repay his merit is enough.", idiomatic: "Court ministers ought to have spoken plainly, saying, 'Your Majesty's favor and reward of the former Grand General to repay his merit is enough." },
  { zh: "間者輔臣顓政，貴戚太盛，君臣之分不明，請罷霍氏三侯皆就第；", literal: "Recently assisting ministers have monopolized government, noble kin are too powerful, and the distinction between ruler and minister is unclear—we request that the three Huo marquises all retire to their estates;", idiomatic: "Recently assisting ministers have monopolized government, noble kin are too powerful, and the distinction between ruler and minister is unclear—we ask that the three Huo marquises retire to their estates;" },
  { zh: "及衛將軍張安世，宜賜-{几}-杖歸休，時存問召見，以列侯為天子師。", literal: "and Guardian General Zhang Anshi ought to be bestowed a {-几}- bench and staff to retire, with occasional inquiries and summons to audience, serving as the Son of Heaven's teacher in the capacity of a ranked marquis.", idiomatic: "and Guardian General Zhang Anshi ought to be bestowed a bench and staff to retire, with occasional inquiries and summons to audience, serving as the emperor's teacher in the capacity of a ranked marquis." },
  { zh: "』明詔以恩不聽，群臣以義固爭而後許之，天下必以陛下為不忘功德而朝臣為知禮，霍氏世世無所患苦。", literal: "' A clear edict in grace would not heed it; the assembled ministers would firmly contend on principle and only afterward obtain assent—the realm would surely take Your Majesty as not forgetting merit and the court ministers as knowing ritual, and the Huo clan for generations would have no affliction.", idiomatic: "' A clear edict in grace would not heed it; the ministers would firmly contend on principle and only afterward obtain assent—the realm would surely see Your Majesty as not forgetting merit and the court ministers as knowing ritual, and the Huo clan for generations would have no affliction." },
  { zh: "今朝廷不聞直聲，而令明詔自親其文，非策之得者也。", literal: "Now the court hears no forthright voice, yet has a clear edict personally draft its text—this is not a policy that succeeds.", idiomatic: "Now the court hears no forthright voice, yet has a clear edict personally draft its text—this is not sound policy." },
  { zh: "今兩侯已出，人情不相遠，以臣心度之，大司馬及其枝屬必有畏懼之心。", literal: "Now the two marquises have been removed; human feelings are not far apart—in your servant's estimation, the Grand Marshal and his branch kin must have hearts of fear.", idiomatic: "Now the two marquises have been removed; human feelings are not far apart—in your servant's judgment, the Grand Marshal and his kin must be fearful." },
  { zh: "夫近臣自危，非完計也。", literal: "When close ministers feel themselves endangered, it is not a complete plan.", idiomatic: "When close ministers feel endangered, it is not a sound plan." },
  { zh: "臣敞願於廣朝白發其端，直守遠郡，其路無由。", literal: "Your servant Chang wishes to speak plainly in broad court and disclose its root, yet holding a distant commandery, there is no way.", idiomatic: "Your servant Chang wishes to speak plainly in open court and disclose its root, yet holding a distant commandery, has no way to do so." },
  { zh: "唯陛下省察。", literal: "I pray only that Your Majesty examine this.", idiomatic: "I pray only that Your Majesty examine this." },
  { zh: "」上甚善其計，然不召也。", literal: "\" The emperor greatly approved his plan, yet did not summon him.", idiomatic: "\" The emperor greatly approved his plan, yet did not summon him." },
  { zh: "禹、山等家數有妖怪，舉家憂愁。", literal: "In the households of Yu, Shan, and the rest there were several portents; the whole family was anxious and sorrowful.", idiomatic: "In the households of Yu, Shan, and the rest there were several portents; the whole family was anxious and sorrowful." },
  { zh: "山曰：「丞相擅減宗廟羔、菟、蛙，可以此罪也。", literal: "Shan said: \"The chancellor on his own authority reduced the ancestral temple's lambs, rabbits, and frogs—we can use this as a charge.", idiomatic: "Shan said, \"The chancellor on his own authority reduced the ancestral temple's lambs, rabbits, and frogs—we can use this as a charge." },
  { zh: "」謀令太后為博平君置酒，召丞相、平恩侯以下，使范明友、鄧廣漢承太后制引斬之，因廢天子而立禹。", literal: "\" They plotted to have the Empress Dowager hold a banquet for Lady Bo Ping, summon the chancellor, Marquis of Ping'en, and those below, and have Fan Mingyou and Deng Guanghan act on the Empress Dowager's command to lead them out and behead them, then depose the Son of Heaven and establish Yu.", idiomatic: "\" They plotted to have the Empress Dowager hold a banquet for Lady Bo Ping, summon the chancellor, Marquis of Ping'en, and those below, and have Fan Mingyou and Deng Guanghan act on the Empress Dowager's command to lead them out and behead them, then depose the emperor and establish Yu." },
  { zh: "約定，未發，雲拜為玄菟太守，太中大夫任宣為代郡太守。", literal: "The agreement was made but not yet launched; Yun was appointed Governor of Xuantu and Grandee of the Palace Ren Xuan was appointed Governor of Dai commandery.", idiomatic: "The agreement was made but not yet launched; Yun was appointed Governor of Xuantu and Palace Grandee Ren Xuan was appointed Governor of Dai." },
  { zh: "會事發覺，秋，七月，雲、山、明友自殺，顯、禹、廣漢等捕得；", literal: "Just then the affair was discovered. Autumn, seventh month: Yun, Shan, and Mingyou killed themselves; Xian, Yu, Guanghan, and the rest were captured;", idiomatic: "Just then the affair was discovered. In autumn, the seventh month, Yun, Shan, and Mingyou killed themselves; Xian, Yu, Guanghan, and the rest were captured;" },
  { zh: "禹要斬，顯及諸女昆弟皆棄市；", literal: "Yu was beheaded at the waist; Xian and all the daughters and brothers were executed in the market;", idiomatic: "Yu was beheaded at the waist; Xian and all the daughters and brothers were executed in the market;" },
  { zh: "與霍氏相連坐誅滅者數十家。", literal: "those implicated with the Huo clan and jointly punished by extermination numbered several tens of households.", idiomatic: "several tens of households implicated with the Huo clan were jointly exterminated." },
  { zh: "太僕杜延年以霍氏舊人，亦坐免官。", literal: "Grand Master of Studs Du Yannian, as an old associate of the Huo clan, was also convicted and dismissed from office.", idiomatic: "Grand Master of Studs Du Yannian, as an old associate of the Huo clan, was also convicted and dismissed." },
  { zh: "八月，己酉，皇后霍氏廢，處昭台宮，乙丑，詔封告霍氏反謀者男子張章、期門董忠、左曹楊惲、侍中金安上、史高皆為列侯。", literal: "Eighth month, day jiyou: Empress Huo was deposed and placed in Zhaotai Palace. Day yichou: an edict enfeoffed as ranked marquises the men who reported the Huo clan's rebellion—Zhang Zhang, Barrier Gate Dong Zhong, Left Censor-in-Chief Yang Yun, Palace Attendant Jin Anshang, and Shi Gao.", idiomatic: "In the eighth month, on day jiyou, Empress Huo was deposed and placed in Zhaotai Palace. On day yichou, an edict enfeoffed as ranked marquises Zhang Zhang, Barrier Gate Dong Zhong, Left Censor-in-Chief Yang Yun, Palace Attendant Jin Anshang, and Shi Gao, who had reported the Huo rebellion." },
  { zh: "惲，丞相敞子；", literal: "Yun was Chancellor Chang's son;", idiomatic: "Yun was Chancellor Chang's son;" },
  { zh: "安上，車騎將軍日磾弟子；", literal: "Anshang was Cavalry-and-Chariots General Rizhu's nephew;", idiomatic: "Anshang was Cavalry-and-Chariots General Rizhu's nephew;" },
  { zh: "高，史良娣兄子也。", literal: "Gao was Lady Shi Liangdi's brother's son.", idiomatic: "Gao was Lady Shi Liangdi's brother's son." },
  { zh: "初，霍氏奢侈，茂陵徐生曰：「霍氏必亡。", literal: "Earlier, the Huo clan was extravagant; Xu Sheng of Maoling said: \"The Huo clan will surely perish.", idiomatic: "Earlier, the Huo clan was extravagant; Xu Sheng of Maoling said, \"The Huo clan will surely perish." },
  { zh: "夫奢則不遜，不遜則侮上。", literal: "Extravagance leads to lack of deference; lack of deference leads to insulting one's superior.", idiomatic: "Extravagance leads to lack of deference; lack of deference leads to insulting one's superior." },
  { zh: "侮上者，逆道也，在人之右，眾必害之。", literal: "One who insults his superior violates the Way; standing to men's right, the multitude will surely harm him.", idiomatic: "Insulting one's superior violates the Way; standing above others, the multitude will surely harm you." },
  { zh: "霍氏秉權日久，害之者多矣。", literal: "The Huo clan has held power long; those who would harm them are many.", idiomatic: "The Huo clan has held power long; those who would harm them are many." },
  { zh: "天下害之，而又行以逆道，不亡何待！", literal: "All under Heaven would harm them, and they also act by the rebellious Way—if they do not perish, what are we waiting for!", idiomatic: "All under Heaven would harm them, and they also act rebelliously—if they do not perish, what are we waiting for!" },
  { zh: "」乃上疏言：「霍氏泰盛，陛下即愛厚之，宜以時抑制，無使至亡。", literal: "\" Thereupon he submitted a memorial, saying: \"The Huo clan is excessively grand; even if Your Majesty loves and favors them, you ought in good time to restrain them and not let them reach ruin.", idiomatic: "\" Thereupon he submitted a memorial, saying, \"The Huo clan is excessively powerful; even if Your Majesty loves and favors them, you ought in good time to restrain them and not let them reach ruin." },
  { zh: "」書三上，輒報聞。", literal: "\" The memorial was submitted three times; each time the reply was merely 'noted.'", idiomatic: "\" The memorial was submitted three times; each time the reply was merely noted." },
  { zh: "其後霍氏誅滅，而告霍氏者皆封，人為徐生上書曰：「臣聞客有過主人者，見其灶直突，傍有積薪，客謂主人：『更為曲突，遠徙其薪，不者且有火患。", literal: "Afterward the Huo clan was exterminated and those who reported the Huo clan were all enfeoffed; a man submitted a memorial on Xu Sheng's behalf, saying: \"Your servant has heard that a guest who visited his host saw the stove with a straight chimney and piled firewood beside it. The guest said to the host: 'Bend the chimney and move the firewood far away, or else there will soon be a fire disaster.", idiomatic: "Afterward the Huo clan was exterminated and those who reported them were all enfeoffed; a man submitted a memorial on Xu Sheng's behalf, saying, \"Your servant has heard that a guest visiting his host saw the stove with a straight chimney and piled firewood beside it. The guest said to the host, 'Bend the chimney and move the firewood far away, or there will soon be a fire." },
  { zh: "』主人嘿然不應。", literal: "' The host murmured assent but did not respond.", idiomatic: "' The host murmured but did not respond." },
  { zh: "俄而家果失火，鄰里共救之，幸而得息。", literal: "Before long the house indeed caught fire; neighbors jointly rescued it and by luck were able to extinguish it.", idiomatic: "Before long the house indeed caught fire; neighbors jointly rescued it and by luck extinguished it." },
  { zh: "於是殺牛置酒，謝其鄰人，灼爛者在於上行，餘各以功次坐，而不錄言曲突者。", literal: "Thereupon he killed an ox and set out wine to thank his neighbors; those with scorched heads sat in the upper places, the rest each sat by merit in order, but he did not record the one who spoke of bending the chimney.", idiomatic: "Thereupon he killed an ox and set out wine to thank his neighbors; those with scorched heads sat in the upper places, the rest by merit in order, but he did not reward the one who spoke of bending the chimney." },
  { zh: "人謂主人曰：『鄉使聽客之言，不費牛酒，終亡火患。", literal: "Someone said to the host: 'If you had earlier heeded the guest's words, you would not have spent ox and wine and would ultimately have had no fire disaster.", idiomatic: "Someone said to the host, 'If you had earlier heeded the guest's words, you would not have spent ox and wine and would ultimately have had no fire." },
  { zh: "今論功而請賓，曲突徙薪無恩澤，焦頭爛額為上客邪？", literal: "Now in discussing merit and treating guests, bending the chimney and moving firewood receives no favor, while scorched heads and burned brows are honored guests?'", idiomatic: "Now in rewarding merit and treating guests, bending the chimney and moving firewood receives no favor, while scorched heads and burned brows are honored guests?'" },
  { zh: "』主人乃寤而請之。", literal: "' The host thereupon awoke and invited him.", idiomatic: "' The host thereupon understood and invited him." },
  { zh: "今茂陵徐福，數上書言霍氏且有變，宜防絕之。", literal: "Now Xu Fu of Maoling repeatedly submitted memorials saying the Huo clan would soon have a change and ought to be prevented and cut off.", idiomatic: "Now Xu Fu of Maoling repeatedly submitted memorials saying the Huo clan would soon rebel and ought to be prevented." },
  { zh: "鄉使福說得行，則國無裂土出爵之費，臣無逆亂誅滅之敗。", literal: "If earlier Fu's counsel had been carried out, the state would have had no expense of carving territory and issuing ranks, and your servants would have had no disaster of rebellion and extermination.", idiomatic: "If earlier Fu's counsel had been carried out, the state would have had no expense of carving territory and issuing ranks, and your servants would have had no disaster of rebellion and extermination." },
  { zh: "往事既已，而福獨不蒙其功，唯陛下察之，貴徙薪曲突之策，使居焦髮灼爛之右。", literal: "Past affairs are already done, yet Fu alone did not receive reward for his merit—I pray only that Your Majesty examine this, value the policy of moving firewood and bending the chimney, and place it above scorched hair and burned flesh.", idiomatic: "Past affairs are already done, yet Fu alone received no reward—I pray Your Majesty examine this, value the policy of moving firewood and bending the chimney, and place it above scorched hair and burned flesh." },
  { zh: "」上乃賜福帛十匹，後以為郎。", literal: "\" The emperor thereupon bestowed on Fu ten bolts of silk and later made him a Gentleman.", idiomatic: "\" The emperor bestowed on Fu ten bolts of silk and later made him a Gentleman." },
  { zh: "帝初立，謁見高廟，大將軍光驂乘，上內嚴憚之，若有芒刺在背。", literal: "When the emperor first took the throne and paid court at the High Temple, Grand General Guang rode beside him in the carriage; inwardly the emperor was sternly in awe of him, as if thorns were in his back.", idiomatic: "When the emperor first took the throne and paid court at the High Temple, Grand General Guang rode beside him in the carriage; inwardly the emperor was in awe of him, as if thorns were in his back." },
  { zh: "後車騎將軍張安世代光驂乘，天子從容肆體，甚安近焉。", literal: "Later Cavalry-and-Chariots General Zhang Anshi replaced Guang riding beside him; the Son of Heaven was at ease and relaxed his body, very comfortable and close.", idiomatic: "Later Cavalry-and-Chariots General Zhang Anshi replaced Guang riding beside him; the emperor was at ease and relaxed, very comfortable and close." },
  { zh: "及光身死而宗族竟誅，故俗傳霍氏之禍萌於驂乘。", literal: "When Guang died in person and the clan was ultimately exterminated, therefore popular tradition says the Huo clan's disaster sprouted from riding beside the carriage.", idiomatic: "When Guang died and the clan was ultimately exterminated, popular tradition says the Huo clan's disaster sprouted from riding beside the carriage." },
  { zh: "後十二歲，霍-{后}-復徙雲林館，乃自殺。", literal: "Twelve years later, Huo-{后}- was again relocated to Yunlin Lodge and thereupon killed herself.", idiomatic: "Twelve years later, Empress Huo was again relocated to Yunlin Lodge and thereupon killed herself." },
  { zh: ":班固贊曰：霍光受襁褓之托，任漢室之寄，匡國家，安社稷，擁昭，立宣，雖周公、阿衡何以加此！", literal: ": Ban Gu's eulogy says: Huo Guang received the entrustment of the swaddling-clothes age and bore the Han house's commission; he rectified the state, secured the altars of soil and grain, enthroned Zhao, and established Xuan—even the Duke of Zhou and Ah Heng—how could they surpass this!", idiomatic: ": Ban Gu's eulogy says: Huo Guang received the entrustment of the infant heir and bore the Han house's commission; he rectified the state, secured the realm, enthroned Zhao, and established Xuan—even the Duke of Zhou and Yi Yin—how could they surpass this!" },
  { zh: "然光不學亡術，闇於大理；", literal: "Yet Guang did not study and lacked method; he was dark to great principle;", idiomatic: "Yet Guang did not study and lacked method; he was blind to great principle;" },
  { zh: "陰妻邪謀，立女為-{后}-，湛溺盈溢之欲，以增顛覆之禍，死財三年，宗族誅夷，哀哉！", literal: "his wife secretly plotted wickedly, established his daughter as {后}-, steeped and drowned in overflowing desire, thereby increasing the disaster of overturning; three years after his death the clan was exterminated—alas!", idiomatic: "his wife secretly plotted wickedly, established his daughter as empress, steeped in overflowing desire, thereby increasing the disaster of overturning; three years after his death the clan was exterminated—alas!" },
  { zh: ":臣光曰：霍光之輔漢室，可謂忠矣；", literal: ": Your servant Guang says: Huo Guang's assisting the Han house may be called loyal;", idiomatic: ": Your servant Guang says: Huo Guang's assisting the Han house may be called loyal;" },
  { zh: "然卒不能庇其宗，何也？", literal: "yet in the end he could not protect his clan—why?", idiomatic: "yet in the end he could not protect his clan—why?" },
  { zh: "夫威福者，人君之器也。", literal: "Authority and favor are the sovereign's instruments.", idiomatic: "Authority and favor are the sovereign's instruments." },
  { zh: "人臣執之，久而不歸，鮮不及矣。", literal: "When ministers hold them and long do not return them, few fail to come to ruin.", idiomatic: "When ministers hold them and long fail to return them, few escape disaster." },
  { zh: "以孝昭之明，十四而知上官桀之詐，固可以親政矣，況孝宣十九即位，聰明剛毅，知民疾苦，而光久專大柄，不知避去，多置私黨，充塞朝廷，使人主蓄憤於上，吏民積怨於下，切齒側目，待時而發，其得免於身幸矣，況子孫以驕侈趣之哉！", literal: "With Emperor Zhao of Filial Piety's clarity—at fourteen knowing Shangguan Jie's deceit—he surely could have personally governed; how much more Emperor Xuan of Filial Piety, who at nineteen took the throne, was intelligent, resolute, and knew the people's hardships—yet Guang long monopolized the great handle, did not know to withdraw, placed many private partisans filling the court, made the lord above store anger, officials and people below accumulate resentment, gnashing teeth and casting sidelong glances, waiting for the time to strike; that he escaped with his person was luck—how much more when sons and grandsons were driven toward arrogance and extravagance!", idiomatic: "With Emperor Zhao's clarity—at fourteen he knew Shangguan Jie's deceit—he surely could have governed in person; how much more Emperor Xuan, who took the throne at nineteen, was intelligent, resolute, and knew the people's hardships—yet Guang long monopolized power, did not know to withdraw, placed many private partisans who filled the court, made the ruler above store anger and officials and people below accumulate resentment, gnashing teeth and watching sidelong, waiting for the moment to strike; that he escaped with his life was luck—how much more when sons and grandsons were driven toward arrogance and extravagance!" },
  { zh: "雖然，向使孝宣專以祿秩賞賜富其子孫，使之食大縣，奉朝請，亦足以報盛德矣；", literal: "Even so, had Emperor Xuan of Filial Piety solely used salary ranks, rewards, and gifts to enrich his sons and grandsons, had them eat great counties, and attend court audiences, that would also have been enough to repay his great virtue;", idiomatic: "Even so, had Emperor Xuan solely used salaries, rewards, and gifts to enrich his sons and grandsons, had them hold great counties and attend court audiences, that would have been enough to repay his great virtue;" },
  { zh: "乃復任之以政，授之以兵，及事叢衅積，更加裁奪，遂至怨懼以生邪謀，豈徒霍氏之自禍哉？", literal: "yet he again entrusted them with government and handed them troops; when affairs piled up and grievances accumulated and he further cut and seized, it reached the point that resentment and fear bred wicked plots—is it only the Huo clan's self-brought disaster?", idiomatic: "yet he again entrusted them with government and handed them troops; when affairs piled up and grievances accumulated and he further cut and seized their power, resentment and fear bred wicked plots—is it only the Huo clan's self-brought disaster?" },
  { zh: "亦孝宣醞釀以成之也。", literal: "Emperor Xuan of Filial Piety also brewed and completed it.", idiomatic: "Emperor Xuan also brewed and brought it about." },
  { zh: "昔鬬椒作亂於楚，莊王滅其族而赦箴尹克黃，以為子文無後，何以勸善。", literal: "Formerly Dou Jiao made rebellion in Chu; King Zhuang exterminated his clan yet pardoned Supervisor of the Girdle Ke Huang, thinking that with Ziwen having no posterity, how could one encourage good.", idiomatic: "Formerly Dou Jiao rebelled in Chu; King Zhuang exterminated his clan yet pardoned Supervisor of the Girdle Ke Huang, reasoning that with Ziwen having no posterity, how could one encourage good." },
  { zh: "夫以顯、禹、雲、山之罪，雖應夷滅，而光之忠勳不可不祀；", literal: "For the offenses of Xian, Yu, Yun, and Shan, though they deserved extermination to the last, Guang's loyal merit could not go unhonored;", idiomatic: "For the offenses of Xian, Yu, Yun, and Shan, though they deserved extermination to the last, Guang's loyal merit could not go unhonored;" },
  { zh: "遂使家無噍類，孝宣亦少恩哉！", literal: "yet he made the family without a mouthful left—Emperor Xuan of Filial Piety was also sparing in grace!", idiomatic: "yet he left not a mouthful in the family—Emperor Xuan was also sparing in grace!" },
  { zh: "----6九月，詔減天下鹽賈。", literal: "----6 In the ninth month, an edict reduced salt merchants throughout the realm.", idiomatic: "----6 In the ninth month, an edict reduced salt merchants throughout the realm." },
  { zh: "又令郡國歲上系囚以掠笞若瘐死者，所坐縣、名、爵、-{里}-，丞相、御史課殿最以聞。", literal: "He also ordered the commanderies and states yearly to report prisoners held who died from flogging or from illness in custody, with the county of offense, name, rank, and -{里}-; the chancellor and censor graded palace and worst and reported.", idiomatic: "He also ordered the commanderies and states yearly to report prisoners who died from flogging or illness in custody, with the county of offense, name, rank, and -{里}-; the chancellor and censor graded them and reported." },
  { zh: "----7十二月，清河王年坐內亂廢，遷房陵。", literal: "----7 In the twelfth month, the King of Qinghe, Nian, was deposed for internal disorder and moved to Fangling.", idiomatic: "----7 In the twelfth month, the King of Qinghe, Nian, was deposed for internal disorder and moved to Fangling." },
  { zh: "----8是歲，北海太守廬江朱邑以治行第一入為大司農，勃海太守龔遂入為水衡都尉。", literal: "----8 That year, Zhu Yi of Lujiang, Governor of Beihai, entered office as Grand Minister of Agriculture for foremost governance, and Gong Sui, Governor of Bohai, entered as Colonel of the Water Balance.", idiomatic: "----8 That year, Zhu Yi of Lujiang, Governor of Beihai, entered office as Grand Minister of Agriculture for foremost governance, and Gong Sui, Governor of Bohai, entered as Colonel of the Water Balance." },
  { zh: "先是，勃海左右郡歲饑，盜賊並起，二千石不能禽制。", literal: "Earlier, the commanderies left and right of Bohai yearly suffered famine; bandits arose together, and the two-thousand-bushel officials could not capture and control them.", idiomatic: "Earlier, the commanderies around Bohai yearly suffered famine; bandits arose together, and the governors could not capture and control them." },
  { zh: "上選能治者，丞相、御史舉故昌邑郎中令龔遂，上拜為勃海太守。", literal: "The emperor selected one who could govern; the chancellor and censor recommended the former Chamberlain of the Palace of Changyi, Gong Sui, and the emperor appointed him Governor of Bohai.", idiomatic: "The emperor selected one who could govern; the chancellor and censor recommended the former Chamberlain of the Palace of Changyi, Gong Sui, and the emperor appointed him Governor of Bohai." },
  { zh: "召見，問：「何以治勃海，息其盜賊？", literal: "He was summoned and seen; the emperor asked: \"By what means will you govern Bohai and quiet its bandits?", idiomatic: "He was summoned and asked, \"By what means will you govern Bohai and quiet its bandits?" },
  { zh: "」對曰：「海瀕遐遠，不沾聖化，其民困於饑寒而吏不恤，故使陛下赤子盜弄陛下之兵於潢池中耳。", literal: "\" He replied: \"The sea's edge is remote and far, untouched by sagely transformation; its people are distressed by hunger and cold while officials do not pity them—therefore Your Majesty's red infants play with Your Majesty's troops in the muddy pool.", idiomatic: "\" He replied, \"The seacoast is remote and far, untouched by sagely transformation; its people suffer hunger and cold while officials do not pity them—therefore Your Majesty's own children play with Your Majesty's troops in the muddy pool." },
  { zh: "今欲使臣勝之邪，將安之也？", literal: "Now does Your Majesty wish your subject to defeat them, or to settle them?", idiomatic: "Now does Your Majesty wish your subject to defeat them, or to settle them?" },
  { zh: "」上曰：「選用賢良，固欲安之也。", literal: "\" The emperor said: \"In selecting and employing the worthy and good, I surely wish to settle them.", idiomatic: "\" The emperor said, \"In selecting and employing the worthy and good, I surely wish to settle them." },
  { zh: "」遂曰：「臣聞治亂民猶治亂繩，不可急也；", literal: "\" Sui said: \"Your subject has heard that governing chaotic people is like governing a tangled rope—it cannot be hurried;", idiomatic: "\" Sui said, \"Your subject has heard that governing chaotic people is like untangling a rope—it cannot be hurried;" },
  { zh: "唯緩之，然後可治。", literal: "only by easing it can it then be governed.", idiomatic: "only by easing it can it then be governed." },
  { zh: "臣願丞相、御史且無拘臣以文法，得一切便宜從事。", literal: "Your subject wishes the chancellor and censor for the time being not to bind your subject with written law, and to obtain leave to act expediently in all matters.", idiomatic: "Your subject asks the chancellor and censor for the time being not to bind your subject with written law, and to be allowed to act expediently in all matters." },
  { zh: "」上許焉，加賜黃金贈遣。", literal: "\" The emperor approved, additionally bestowed gold, and sent him off with gifts.", idiomatic: "\" The emperor approved, additionally bestowed gold, and sent him off with gifts." },
  { zh: "乘傳至勃海界，郡聞新太守至，發兵以迎。", literal: "Riding the relay carriage to Bohai's border, the commandery hearing the new governor had arrived, raised troops to welcome him.", idiomatic: "Riding the relay carriage to Bohai's border, the commandery hearing the new governor had arrived, raised troops to welcome him." },
  { zh: "遂皆遣還。", literal: "Sui sent them all back.", idiomatic: "Sui sent them all back." },
  { zh: "移書敕屬縣：「悉罷逐捕盜賊吏，諸持鍺、鉤、田器者皆為良民，吏毋得問；", literal: "He sent a letter ordering the subordinate counties: \"Entirely dismiss the officers who pursue and capture bandits; all who hold hoes, hooks, and field tools are good people—officers must not question them;", idiomatic: "He sent a letter ordering the subordinate counties, \"Entirely dismiss the officers who pursue and capture bandits; all who hold hoes, hooks, and field tools are good people—officers must not question them;" },
  { zh: "持兵者乃為賊。", literal: "those who hold weapons are the bandits.", idiomatic: "those who hold weapons are the bandits." },
  { zh: "」遂單車獨行至府。", literal: "\" Sui alone in a single carriage went alone to the headquarters.", idiomatic: "\" Sui alone in a single carriage went to the headquarters." },
  { zh: "盜賊聞遂教令，即時解散，棄其兵弩而持鉤、鋤，於是悉平，民安土樂業。", literal: "The bandits hearing Sui's teaching and orders immediately dispersed, abandoned their crossbows and weapons and took hooks and hoes; thereupon all was pacified, and the people were secure on their land and delighted in their work.", idiomatic: "The bandits hearing Sui's orders immediately dispersed, abandoned their crossbows and weapons and took hooks and hoes; thereupon all was pacified, and the people were secure on their land and delighted in their work." },
  { zh: "遂乃開倉廩假貧民，選用良吏尉安牧養焉。", literal: "Sui thereupon opened the granaries and lent to the poor, selected and employed good officials to comfort, settle, and nurture them.", idiomatic: "Sui thereupon opened the granaries and lent to the poor, selected and employed good officials to comfort, settle, and nurture them." },
  { zh: "遂見齊俗奢侈，好末技，不田作，乃躬率以儉約，勸民務農桑，各以口率種樹畜養。", literal: "Sui saw Qi customs were extravagant, fond of secondary crafts, and did not till; he thereupon personally led with frugality, urged the people to devote themselves to farming and sericulture, and each according to mouths led in planting trees and raising livestock.", idiomatic: "Sui saw Qi customs were extravagant, fond of secondary crafts, and did not till; he thereupon personally led with frugality, urged the people to devote themselves to farming and sericulture, and each household planted trees and raised livestock according to its mouths." },
  { zh: "民有帶持刀劍者，使賣劍買牛，賣刀買犢，曰：「何為帶牛佩犢！", literal: "Where people wore swords and blades, he had them sell swords to buy oxen and sell knives to buy calves, saying: \"Why wear an ox and hang a calf!", idiomatic: "Where people wore swords and blades, he had them sell swords to buy oxen and sell knives to buy calves, saying, \"Why wear an ox and hang a calf!" },
  { zh: "」勞來循行，郡中皆有畜積，獄訟止息。", literal: "\" He comforted and came and went on inspection; throughout the commandery all had stored accumulations, and prison suits ceased.", idiomatic: "\" He comforted them and went about on inspection; throughout the commandery all had stores, and litigation ceased." },
  { zh: "----9烏孫公主女為龜茲王絳賓夫人。", literal: "----9 The Wusun princess's daughter became the consort of the King of Kucha, Jiangbin.", idiomatic: "----9 The Wusun princess's daughter became the consort of the King of Kucha, Jiangbin." },
  { zh: "絳賓上書言：「得尚漢外孫，願與公主女俱入朝。", literal: "Jiangbin memorialized, saying: \"Having obtained in marriage Han's outer granddaughter, I wish together with the princess's daughter to enter court.", idiomatic: "Jiangbin memorialized, \"Having obtained in marriage Han's outer granddaughter, I wish together with the princess's daughter to enter court." },
  { zh: "1春，正月，龜茲王及其夫人來朝；", literal: "1 In spring, the first month, the King of Kucha and his consort came to court;", idiomatic: "1 In spring, the first month, the King of Kucha and his consort came to court;" },
  { zh: "皆賜印綬，夫人號稱公主，賞賜甚厚。", literal: "both were bestowed seals and ribbons; the consort was styled princess, and rewards were very generous.", idiomatic: "both were bestowed seals and ribbons; the consort was styled princess, and rewards were very generous." },
  { zh: "----2初作杜陵。", literal: "----2 For the first time Duling was built.", idiomatic: "----2 For the first time Duling was built." },
  { zh: "徙丞相、將軍、列侯、吏二千石、訾百萬者杜陵。", literal: "The chancellor, generals, ranked marquises, two-thousand-bushel officials, and those with assessments of a million were moved to Duling.", idiomatic: "The chancellor, generals, marquises, two-thousand-bushel officials, and those with assessments of a million were moved to Duling." },
  { zh: "----3三月，詔以鳳皇集泰山、陳留，甘露降未央宮，赦天下。", literal: "----3 In the third month, an edict because phoenixes gathered at Mount Tai and Chenliu and sweet dew descended at Weiyang Palace amnestied all under Heaven.", idiomatic: "----3 In the third month, an edict because phoenixes gathered at Mount Tai and Chenliu and sweet dew descended at Weiyang Palace granted amnesty to all under Heaven." },
  { zh: "----4有司復言悼園宜稱尊號曰皇考；", literal: "----4 The responsible offices again said the Garden of Mourning should be given the honored title Imperial Father;", idiomatic: "----4 The responsible offices again said the Garden of Mourning should be given the honored title Imperial Father;" },
  { zh: "夏，五月，立皇考廟。", literal: "in summer, the fifth month, the Imperial Father Temple was established.", idiomatic: "in summer, the fifth month, the Imperial Father Temple was established." },
  { zh: "----5冬，置建章衛尉。", literal: "----5 In winter, the Commandant of Guards for Jianzhang was established.", idiomatic: "----5 In winter, the Commandant of Guards for Jianzhang was established." },
  { zh: "----6趙廣漢好用世吏子孫新進年少者，專厲強壯蠭氣，見事風生，無所迴避，率多果敢之計，莫為持難，終以此敗。", literal: "----6 Zhao Guanghan was fond of employing sons and grandsons of hereditary officials who were newly advanced and young; he specialized in fierce, strong, waspish spirit; when he saw an affair wind arose; he avoided nothing; he mostly used bold, decisive plans and none held difficulty—he ultimately failed because of this.", idiomatic: "----6 Zhao Guanghan was fond of employing young sons and grandsons of hereditary officials newly advanced in office; he specialized in fierce, aggressive spirit; when he saw an affair he acted like the wind; he avoided nothing; he mostly used bold, decisive plans and none held back—he ultimately failed because of this." },
  { zh: "廣漢以私怨論殺男子榮畜，人上書言之，事下丞相、御史按驗。", literal: "Guanghan because of private resentment judged and killed the man Rong Chu; people memorialized it; the matter was sent down to the chancellor and censor to investigate and verify.", idiomatic: "Guanghan because of private resentment judged and killed the man Rong Chu; people memorialized it; the matter was sent down to the chancellor and censor to investigate." },
  { zh: "廣漢疑丞相夫人殺侍婢，欲以此脅丞相，丞相按之愈急。", literal: "Guanghan suspected the chancellor's wife had killed a serving maid and wished thereby to coerce the chancellor; the chancellor's investigation grew all the more urgent.", idiomatic: "Guanghan suspected the chancellor's wife had killed a serving maid and wished thereby to coerce the chancellor; the chancellor's investigation grew all the more urgent." },
  { zh: "廣漢乃將吏卒入丞相府，召其夫人跪庭下受辭，收奴婢十餘人去。", literal: "Guanghan thereupon led officers and soldiers into the chancellor's headquarters, summoned his wife to kneel in the courtyard below to receive interrogation, and took away more than ten slave girls.", idiomatic: "Guanghan thereupon led officers and soldiers into the chancellor's headquarters, summoned his wife to kneel in the courtyard to be interrogated, and took away more than ten slave girls." },
  { zh: "丞相上書自陳，事下廷尉治，實丞相自以過譴笞傅婢，出至外第乃死，不如廣漢言。", literal: "The chancellor memorialized in self-explanation; the matter was sent down to the Director of Justice to try; in fact the chancellor himself because of fault had reproached and flogged the attendant maid, and she died only after going out to the outer residence—not as Guanghan said.", idiomatic: "The chancellor memorialized in self-explanation; the matter was sent down to the Director of Justice; in fact the chancellor himself because of fault had reproached and flogged the attendant maid, and she died only after going out to the outer residence—not as Guanghan said." },
  { zh: "帝惡之，下廣漢廷尉獄。", literal: "The emperor detested it and sent Guanghan down to the Director of Justice's prison.", idiomatic: "The emperor detested it and sent Guanghan to the Director of Justice's prison." },
  { zh: "吏民守闕號泣者數萬人，或言：「臣生無益縣官，願代趙京兆死，使牧養小民！", literal: "Officials and people who guarded the gate and wept and wailed numbered tens of thousands; some said: \"Your subject's life has been of no use to the district officials—I wish to die in place of Zhao, Governor of Jingzhao, and let him nurture the little people!", idiomatic: "Officials and people who guarded the gate and wept numbered tens of thousands; some said, \"Your subject's life has been of no use to the government—I wish to die in place of Zhao, Governor of Jingzhao, and let him nurture the people!" },
  { zh: "」廣漢竟坐要斬。", literal: "\" Guanghan in the end was punished with decapitation at the waist.", idiomatic: "\" Guanghan in the end was executed by decapitation at the waist." },
  { zh: "廣漢為京兆尹，廉明，威制豪強，小民得職，百姓追思歌之。", literal: "Guanghan as Governor of Jingzhao was incorrupt and clear, awed and restrained the powerful, and the little people obtained their posts; the people afterward remembered and sang of him.", idiomatic: "Guanghan as Governor of Jingzhao was incorrupt and clear, awed and restrained the powerful, and the common people obtained their due; the people afterward remembered and sang of him." },
  { zh: "----7是歲，少府宋疇坐議「鳳皇下彭城，未至京師，不足美」，貶為泗水太傅。", literal: "----7 That year, Song Chuo, Director of the Privy Purse, was punished for discussing that \"the phoenix descended at Pengcheng and did not reach the capital—it is not enough to praise\" and was demoted to Grand Tutor of Sishui.", idiomatic: "----7 That year, Song Chuo, Director of the Privy Purse, was punished for discussing that \"the phoenix descended at Pengcheng and did not reach the capital—it is not enough to praise\" and was demoted to Grand Tutor of Sishui." },
  { zh: "----8上遷博士、諫大夫通政事者補郡國守相，以蕭望之為平原太守。", literal: "----8 The emperor moved erudites and remonstrance grandees who understood government affairs to fill commandery and state governorships and chancellorships; Xiao Wangzhi was made Governor of Pingyuan.", idiomatic: "----8 The emperor moved erudites and remonstrance grandees who understood government affairs to fill governorships and chancellorships; Xiao Wangzhi was made Governor of Pingyuan." },
  { zh: "望之上疏曰：「陛下哀愍百姓，恐德之不究，悉出諫官以補郡吏。", literal: "Wangzhi submitted a memorial, saying: \"Your Majesty pities the hundred surnames and fears your virtue does not reach completion, and has sent out all remonstrance officials to fill commandery posts.", idiomatic: "Wangzhi submitted a memorial, \"Your Majesty pities the people and fears your virtue does not reach completion, and has sent out all remonstrance officials to fill commandery posts." },
  { zh: "朝無爭臣，則不知過，所謂憂其末而忘其本者也。", literal: "With no disputing ministers at court, one will not know one's faults—what is called worrying the branch and forgetting the root.", idiomatic: "With no disputing ministers at court, one will not know one's faults—what is called worrying the branch and forgetting the root." },
  { zh: "」上乃徵望之入守少府。", literal: "\" The emperor thereupon summoned Wangzhi in to serve as Director of the Privy Purse.", idiomatic: "\" The emperor thereupon summoned Wangzhi in to serve as Director of the Privy Purse." },
  { zh: "----9東海太守河東尹翁歸，以治郡高第入為右扶風。", literal: "----9 Yin Wengui of Hedong, Governor of Donghai, entered as Governor of Right Fufeng for governing his commandery with top grade.", idiomatic: "----9 Yin Wengui of Hedong, Governor of Donghai, entered as Governor of Right Fufeng for governing his commandery with top grade." },
  { zh: "翁歸為人，公廉明察，郡中吏民賢、不肖及奸邪罪名盡知之。", literal: "Wengui as a man was fair, incorrupt, and clear-sighted; throughout the commandery he thoroughly knew which officials and people were worthy or unworthy and the names of wicked offenses.", idiomatic: "Wengui was fair, incorrupt, and clear-sighted; throughout the commandery he thoroughly knew which officials and people were worthy or unworthy and the names of wicked offenses." },
  { zh: "縣縣各有記籍，自聽其政；", literal: "Each county had its own registry; he himself heard their government;", idiomatic: "Each county had its own registry; he himself heard their government;" },
  { zh: "有急名則少緩之。", literal: "if there was an urgent name he would slightly ease it.", idiomatic: "if there was an urgent name he would slightly ease it." },
  { zh: "吏民小解，輒披籍。", literal: "When officials and people slightly relaxed, he immediately opened the registry.", idiomatic: "When officials and people slightly relaxed, he immediately opened the registry." },
  { zh: "取人必於秋冬課吏大會中及出行縣，不以無事時。", literal: "Taking people he always did at the great autumn-winter review of officials or when going out to the counties—not in times of no business.", idiomatic: "Taking people he always did at the great autumn-winter review of officials or when going out to the counties—not in times of no business." },
  { zh: "其有所取也，以一警百。", literal: "When he took someone, he warned a hundred with one.", idiomatic: "When he took someone, he warned a hundred with one." },
  { zh: "吏民皆服，恐懼，改行自新。", literal: "Officials and people all submitted, feared, and reformed their conduct and renewed themselves.", idiomatic: "Officials and people all submitted, feared, and reformed their conduct and renewed themselves." },
  { zh: "其為扶風，選用廉平疾奸吏以為右職，接待以禮，好惡與同之；", literal: "When he was in Fufeng, he selected and employed incorrupt, fair, and swift-against-wicked officials for the right offices, received them with rites, and shared likes and dislikes with them;", idiomatic: "When he was in Fufeng, he selected and employed incorrupt, fair, and swift-against-wicked officials for the right offices, received them with rites, and shared likes and dislikes with them;" },
  { zh: "其負翁歸，罰亦必行。", literal: "those who failed Wengui—punishment also was surely carried out.", idiomatic: "those who failed Wengui—punishment was also surely carried out." },
  { zh: "然溫良謙退，不以行能驕人，故尤得名譽於朝廷。", literal: "Yet he was gentle, good, humble, and yielding, and did not with conduct and ability look down on others—therefore he especially gained reputation at court.", idiomatic: "Yet he was gentle, good, humble, and yielding, and did not with conduct and ability look down on others—therefore he especially gained reputation at court." },
  { zh: "----10初，烏孫公主少子萬年有寵於莎車王。", literal: "----10 At the beginning, the Wusun princess's younger son Wannian had favor with the King of Shache.", idiomatic: "----10 At the beginning, the Wusun princess's younger son Wannian had favor with the King of Shache." },
  { zh: "莎車王死而無子，時萬年在漢，莎車國人計，欲自托於漢，又欲得烏孫心，上書請萬年為莎車王。", literal: "The King of Shache died without a son; at that time Wannian was in Han; the people of Shache plotted, wishing to entrust themselves to Han and also wishing to win Wusun's heart, and memorialized requesting Wannian as King of Shache.", idiomatic: "The King of Shache died without a son; at that time Wannian was in Han; the people of Shache plotted, wishing to entrust themselves to Han and also wishing to win Wusun's heart, and memorialized requesting Wannian as King of Shache." },
  { zh: "漢許之，遣使者奚充國送萬年。", literal: "Han approved and dispatched the envoy Xi Chongguo to escort Wannian.", idiomatic: "Han approved and dispatched the envoy Xi Chongguo to escort Wannian." },
  { zh: "萬年初立，暴惡，國人不說。", literal: "Wannian had just been installed and was violent and wicked; the people of the state were displeased.", idiomatic: "Wannian had just been installed and was violent and wicked; the people of the state were displeased." },
  { zh: "上令群臣舉可使西域者，前將軍韓增舉上黨馮奉世以衛候使持節送大苑諸國客至伊循城。", literal: "The emperor ordered the ministers to recommend one who could be sent to the Western Regions; former General Han Zeng recommended Feng Fengshi of Shangdang as envoy with staff of authority to escort guests of the various states of the Great Park to Yixun city.", idiomatic: "The emperor ordered the ministers to recommend one who could be sent to the Western Regions; former General Han Zeng recommended Feng Fengshi of Shangdang as envoy with staff of authority to escort guests of the various states of the Great Park to Yixun city." },
  { zh: "會故莎車王弟呼屠徵與旁國共殺其王萬年及漢使者奚充國，自立為王。", literal: "It happened the former King of Shache's younger brother Hutuzheng together with neighboring states jointly killed its king Wannian and the Han envoy Xi Chongguo and installed himself as king.", idiomatic: "It happened the former King of Shache's younger brother Hutuzheng together with neighboring states jointly killed its king Wannian and the Han envoy Xi Chongguo and installed himself as king." },
  { zh: "時匈奴又發兵攻車師城，不能下而去。", literal: "At that time the Xiongnu again dispatched troops to attack the city of Cheshi, could not take it, and departed.", idiomatic: "At that time the Xiongnu again dispatched troops to attack the city of Cheshi, could not take it, and departed." },
  { zh: "莎車遣使揚言「北道諸國已屬匈奴矣」，於是攻劫南道，與歃盟畔漢，從鄯善以西皆絕不通。", literal: "Shache sent envoys proclaiming that \"the states of the northern route already belong to the Xiongnu\"; thereupon they attacked and plundered the southern route, swore blood alliance and turned from Han, and from Shanshan westward all communication was cut off.", idiomatic: "Shache sent envoys proclaiming that \"the states of the northern route already belong to the Xiongnu\"; thereupon they attacked and plundered the southern route, swore blood alliance and turned from Han, and from Shanshan westward all communication was cut off." },
  { zh: "都護鄭吉、校尉司馬憙皆在北道諸國間，奉世與其副嚴昌計，以為不亟擊之，則莎車日強，其勢難制，必危西域，遂以節諭告諸國王，因發其兵，南北道合萬五千人，進擊莎車，攻拔其城。", literal: "Protector-General Zheng Ji and Colonel Sima Xi were both among the states of the northern route; Fengshi with his deputy Yan Chang plotted, thinking that if they did not quickly strike, Shache would daily grow strong, its power hard to control, and the Western Regions would surely be endangered; they thereupon with the staff informed and told the various kings, and thereby raised their troops; north and south routes together fifteen thousand men advanced to strike Shache and stormed and took its city.", idiomatic: "Protector-General Zheng Ji and Colonel Sima Xi were both among the states of the northern route; Fengshi with his deputy Yan Chang plotted, thinking that if they did not quickly strike, Shache would daily grow strong, its power hard to control, and the Western Regions would surely be endangered; they thereupon with the staff informed the various kings and raised their troops; north and south routes together fifteen thousand men advanced to strike Shache and stormed and took its city." },
  { zh: "莎車王自殺，傳其首詣長安，更立它昆弟子為莎車王。", literal: "The King of Shache killed himself; his head was transmitted to Chang'an; another kunmi's younger brother was established as King of Shache.", idiomatic: "The King of Shache killed himself; his head was sent to Chang'an; another kunmi's younger brother was established as King of Shache." },
  { zh: "諸國悉平，威振西域，奉世乃罷兵以聞。", literal: "The various states were all pacified; authority shook the Western Regions; Fengshi thereupon dismissed the troops and reported.", idiomatic: "The various states were all pacified; authority shook the Western Regions; Fengshi thereupon dismissed the troops and reported." },
  { zh: "帝召見韓增曰：「賀將軍所舉得其人。", literal: "The emperor summoned and saw Han Zeng and said: \"Congratulations—what the general recommended obtained the right man.", idiomatic: "The emperor summoned Han Zeng and said, \"Congratulations—what the general recommended obtained the right man." },
  { zh: "奉世遂西至大宛。", literal: "Fengshi thereupon went west as far as Great Yuezhi.", idiomatic: "Fengshi thereupon went west as far as Dayuan." },
  { zh: "大宛聞其斬莎車王，敬之異於它使，得其名馬象龍而還。", literal: "Dayuan hearing he had beheaded the King of Shache honored him differently from other envoys; he obtained its famous horse Elephant Dragon and returned.", idiomatic: "Dayuan hearing he had beheaded the King of Shache honored him differently from other envoys; he obtained its famous horse Elephant Dragon and returned." },
  { zh: "上甚說，議封奉世。", literal: "The emperor was very pleased and debated enfeoffing Fengshi.", idiomatic: "The emperor was very pleased and debated enfeoffing Fengshi." },
  { zh: "丞相、將軍皆以為可，獨少府蕭望之以為：「奉世奉使有指，而擅制違命，發諸國兵，雖有功效，不可以為後法。", literal: "The chancellor and generals all thought it acceptable; only Director of the Privy Purse Xiao Wangzhi thought: \"Fengshi on mission had instructions, yet on his own authority made policy and disobeyed orders, raising the various states' troops—though he had achievement, it cannot be made a later model.", idiomatic: "The chancellor and generals all thought it acceptable; only Director of the Privy Purse Xiao Wangzhi thought, \"Fengshi on mission had instructions, yet on his own authority made policy and disobeyed orders, raising the various states' troops—though he had achievement, it cannot be made a later model." },
  { zh: "即封奉世，開後奉使者利以奉世為比，爭逐發兵，要功萬里之外，為國家生事於夷狄，漸不可長。", literal: "If Fengshi is enfeoffed, it opens the way for later envoys to profit and take Fengshi as a comparison, competing to dispatch troops and demand merit ten thousand li away, creating affairs for the state among the barbarian Di—this gradually cannot be allowed to grow.", idiomatic: "If Fengshi is enfeoffed, it opens the way for later envoys to profit and take Fengshi as a comparison, competing to dispatch troops and demand merit ten thousand li away, creating affairs for the state among the barbarians—this gradually cannot be allowed to grow." },
  { zh: "奉世不宜受封。", literal: "Fengshi is not fit to receive enfeoffment.", idiomatic: "Fengshi is not fit to receive enfeoffment." },
  { zh: "」上善望之議，以奉世為光祿大夫。", literal: "\" The emperor approved Wangzhi's discussion and made Fengshi Palace Counselor.", idiomatic: "\" The emperor approved Wangzhi's discussion and made Fengshi Palace Counselor." },
  { zh: "1春，正月，赦天下。", literal: "1 In spring, the first month, amnesty for all under Heaven.", idiomatic: "1 In spring, the first month, there was an amnesty for all under Heaven." },
  { zh: "----2上欲立皇后，時館陶主母華倢伃及淮陽憲王母張倢伃、楚孝王母衛倢伃皆愛幸。", literal: "----2 The emperor wished to establish an empress; at that time the Princess of Guantao's mother, Lady Hua of Handsome Fairness, and the King of Huaiyang Xian's mother, Lady Zhang of Handsome Fairness, and the King of Chu Xiao's mother, Lady Wei of Handsome Fairness, were all favored.", idiomatic: "----2 The emperor wished to establish an empress; at that time the Princess of Guantao's mother, Lady Hua of Handsome Fairness, and the King of Huaiyang Xian's mother, Lady Zhang of Handsome Fairness, and the King of Chu Xiao's mother, Lady Wei of Handsome Fairness, were all favored." },
  { zh: "上欲立張倢伃為-{后}-；", literal: "The emperor wished to establish Lady Zhang of Handsome Fairness as -{后}-;", idiomatic: "The emperor wished to establish Lady Zhang of Handsome Fairness as -{后}-;" },
  { zh: "久之，懲艾霍氏欲害皇太子，乃更選後宮無子而謹慎者。", literal: "after long time, chastened by the Huo clan's wish to harm the crown prince, he thereupon again selected from the rear palace one without a son who was careful and cautious.", idiomatic: "after long time, chastened by the Huo clan's wish to harm the crown prince, he thereupon again selected from the rear palace one without a son who was careful and cautious." },
  { zh: "二月，乙丑，立長陵王倢伃為皇后，令母養太子；", literal: "In the second month, on yichou, the Lady of Handsome Fairness of the King of Changling was established as empress and ordered to mother and nurture the crown prince;", idiomatic: "In the second month, on yichou, the Lady of Handsome Fairness of the King of Changling was established as empress and ordered to mother and nurture the crown prince;" },
  { zh: "封其父奉光為邛成侯。", literal: "her father Fengguang was enfeoffed as Marquis of Qiongcheng.", idiomatic: "her father Fengguang was enfeoffed as Marquis of Qiongcheng." },
  { zh: "-{后}-無寵，希得進見。", literal: "-{后}- had no favor and rarely obtained advancement to audience.", idiomatic: "-{后}- had no favor and rarely obtained audience." },
  { zh: "----3五月，詔曰：「獄者，萬民之命。", literal: "----3 In the fifth month, an edict said: \"Prisons are the lives of the myriad people.", idiomatic: "----3 In the fifth month, an edict said, \"Prisons are the lives of the myriad people." },
  { zh: "能使生者不怨，死者不恨，則可謂文吏矣。", literal: "If one can make the living not resent and the dead not hate, then one may be called a cultured official.", idiomatic: "If one can make the living not resent and the dead not hate, then one may be called a cultured official." },
  { zh: "今則不然。", literal: "Now it is not so.", idiomatic: "Now it is not so." },
  { zh: "用法或持巧心，析律貳端，深淺不平，奏不如實，上亦亡由知，四方黎民將何仰哉！", literal: "In using law some hold crafty minds, split statutes into two ends, depth and shallowness not level, memorials not as in fact—the above also has no way to know; the four quarters' black-haired people—what will they look up to!", idiomatic: "In using law some hold crafty minds, split statutes into two ends, depth and shallowness not level, memorials not as in fact—the ruler also has no way to know; the people of the four quarters—what will they look up to!" },
  { zh: "二千石各察官屬，勿用此人。", literal: "Let each two-thousand-bushel official examine his subordinates and not employ such persons.", idiomatic: "Let each two-thousand-bushel official examine his subordinates and not employ such persons." },
  { zh: "吏或擅興徭役，飾廚傳，稱過使客，越職逾法以取名譽，譬如踐薄冰以待白日，豈不殆哉！", literal: "Some officials on their own authority raise corvée labor, adorn kitchens and relay stations, praise excess to please travelers, overstep duties and exceed law to seek name and reputation—like treading thin ice waiting for the white day—is it not perilous!", idiomatic: "Some officials on their own authority raise corvée labor, adorn kitchens and relay stations, praise excess to please travelers, overstep duties and exceed law to seek reputation—like treading thin ice waiting for daylight—is it not perilous!" },
  { zh: "今天下頗被疾疫之災，朕甚愍之，其令郡國被災甚者，毋出今年租賦。", literal: "Now all under Heaven is greatly afflicted by plague disaster; We are deeply compassionate; let commanderies and kingdoms where the disaster struck severely not levy this year's rent and tax.", idiomatic: "Now all under Heaven is greatly afflicted by plague; We are deeply moved with pity—let commanderies and kingdoms where the disaster struck severely not levy this year's rent and tax." },
  { zh: "」----4又曰：「聞古天子之名，難知而易諱也；", literal: "\" ----4 He also said: \"I have heard that ancient Son-of-Heaven names are hard to know and easy to taboo;", idiomatic: "\" ----4 He also said, \"I have heard that ancient Son-of-Heaven names are hard to know and easy to taboo;" },
  { zh: "其更諱詢。", literal: "let the taboo-name inquiry be revised.", idiomatic: "let the taboo-name inquiry be revised." },
  { zh: "」----5匈奴大臣皆以為「車師地肥美，近匈奴，使漢得之，多田積穀，必害人國，不可不爭」，由是數遣兵擊車師田者。", literal: "\" ----5 The Xiongnu great ministers all held that \"Cheshi's land is fertile and fine, close to the Xiongnu; if the Han obtain it, farm much and store grain, they will surely harm our state—this cannot go uncontested,\" and thereby repeatedly sent troops to strike those farming Cheshi.", idiomatic: "\" ----5 The Xiongnu great ministers all held that \"Cheshi's land is fertile and fine, close to the Xiongnu; if the Han obtain it, farm much and store grain, they will surely harm our state—this cannot go uncontested,\" and thereby repeatedly sent troops to strike those farming Cheshi." },
  { zh: "鄭吉將渠犁田卒七千餘人救之，為匈奴所圍。", literal: "Zheng Ji led more than seven thousand field soldiers of Queli to rescue them and was surrounded by the Xiongnu.", idiomatic: "Zheng Ji led more than seven thousand field soldiers of Queli to rescue them and was surrounded by the Xiongnu." },
  { zh: "吉上言：「車師去渠犁千餘里，漢兵在渠犁者少，勢不能相救，願益田卒。", literal: "Ji submitted: \"Cheshi is more than a thousand li from Queli; Han troops at Queli are few—the situation cannot allow mutual rescue; your subject wishes increased field soldiers.", idiomatic: "Ji submitted, \"Cheshi is more than a thousand li from Queli; Han troops at Queli are few—the situation cannot allow mutual rescue; your subject wishes increased field soldiers." },
  { zh: "」上與後將軍趙充國等議，欲因匈奴衰弱，出兵擊其右地，使不得復擾西域。", literal: "\" The emperor deliberated with Rear General Zhao Chongguo and others, wishing to exploit the Xiongnu's weakness, send troops to strike their right territory, and keep them from again disturbing the Western Regions.", idiomatic: "\" The emperor deliberated with Rear General Zhao Chongguo and others, wishing to exploit the Xiongnu's weakness, send troops to strike their right territory, and keep them from again disturbing the Western Regions." },
  { zh: "魏相上書諫曰：「臣聞之：救亂誅暴，謂之義兵，兵義者王；", literal: "Wei Xiang submitted a memorial remonstrating: \"Your subject has heard: rescuing disorder and punishing violence is called righteous troops—troops that are righteous make one king;", idiomatic: "Wei Xiang submitted a memorial remonstrating, \"Your subject has heard: rescuing disorder and punishing violence is called righteous troops—troops that are righteous make one king;" },
  { zh: "敵加於己，不得已而起者，謂之應兵，兵應者勝；", literal: "when the enemy presses upon oneself and one rises because there is no alternative, it is called responsive troops—troops that respond win;", idiomatic: "when the enemy presses upon oneself and one rises because there is no alternative, it is called responsive troops—troops that respond win;" },
  { zh: "爭恨小故，不忍憤怒者，謂之忿兵，兵忿者敗；", literal: "contending over small causes and unable to bear angry resentment is called resentful troops—troops that resent lose;", idiomatic: "contending over small causes and unable to bear angry resentment is called resentful troops—troops that resent lose;" },
  { zh: "利人土地、貨寶者，謂之貪兵，兵貪者破；", literal: "coveting others' land and goods and treasures is called greedy troops—troops that are greedy are broken;", idiomatic: "coveting others' land and goods and treasures is called greedy troops—troops that are greedy are broken;" },
  { zh: "恃國家之大，矜民人之眾，欲見威於敵者，謂之驕兵，兵驕者滅。", literal: "relying on the state's greatness, taking pride in the people's multitude, and wishing to display might before the enemy is called arrogant troops—troops that are arrogant perish.", idiomatic: "relying on the state's greatness, taking pride in the people's multitude, and wishing to display might before the enemy is called arrogant troops—troops that are arrogant perish." },
  { zh: "此五者，非但人事，乃天道也。", literal: "These five are not only human affairs—they are Heaven's Way.", idiomatic: "These five are not only human affairs—they are Heaven's Way." },
  { zh: "間者匈奴嘗有善意，所得漢民，輒奉歸之，未有犯於邊境；", literal: "Recently the Xiongnu have at times shown good intent; Han people they obtained they promptly returned—there has been no offense against the border;", idiomatic: "Recently the Xiongnu have at times shown good intent; Han people they obtained they promptly returned—there has been no offense against the border;" },
  { zh: "雖爭屯田車師，不足致意中。", literal: "though they contend over garrison farming at Cheshi, it is insufficient to fix the mind upon.", idiomatic: "though they contend over garrison farming at Cheshi, it is insufficient to fix the mind upon." },
  { zh: "今聞諸將軍欲興兵入其地，臣愚不知此兵何名者也！", literal: "Now your subject hears the various generals wish to raise troops and enter their territory—your subject in his folly does not know what name this army bears!", idiomatic: "Now your subject hears the various generals wish to raise troops and enter their territory—your subject in his folly does not know what name this army bears!" },
  { zh: "今邊郡困乏，父子共犬羊之裘，食草萊之實，常恐不能自存，難以動兵。", literal: "Now the border commanderies are exhausted; fathers and sons together wear dog-and-sheep pelts and eat wild plants' fruit—they constantly fear they cannot preserve themselves; it is hard to move troops.", idiomatic: "Now the border commanderies are exhausted; fathers and sons together wear dog-and-sheep pelts and eat wild plants' fruit—they constantly fear they cannot preserve themselves; it is hard to move troops." },
  { zh: "『軍旅之後，必有凶年，』言民以其愁苦之氣傷陰陽之和也。", literal: "'After armies and campaigns there must be a famine year'—meaning the people with their sorrowful, bitter qi harm the harmony of yin and yang.", idiomatic: "'After armies and campaigns there must be a famine year'—meaning the people with their sorrowful, bitter qi harm the harmony of yin and yang." },
  { zh: "出兵雖勝，猶有後憂，恐災害之變因此以生。", literal: "Sending troops out, though victorious, still has later worry—your subject fears disasters and changes will thereby arise.", idiomatic: "Sending troops out, though victorious, still has later worry—your subject fears disasters and changes will thereby arise." },
  { zh: "今郡國守相多不實選，風俗尤薄，水旱不時。", literal: "Now commandery and kingdom governors and administrators are mostly not truthfully chosen; customs are especially thin; flood and drought come untimely.", idiomatic: "Now commandery and kingdom governors and administrators are mostly not truthfully chosen; customs are especially thin; flood and drought come untimely." },
  { zh: "按今年計子弟殺父兄、妻殺夫者凡二百二十二人，臣愚以為此非小變也。", literal: "According to this year's tally, sons and younger brothers who killed fathers and elder brothers and wives who killed husbands totaled two hundred twenty-two persons—your subject in his folly holds this is no small change.", idiomatic: "According to this year's tally, sons and younger brothers who killed fathers and elder brothers and wives who killed husbands totaled two hundred twenty-two persons—your subject in his folly holds this is no small change." },
  { zh: "今左右不憂此，乃欲發兵報纖介之忿於遠夷，殆孔子所謂『吾恐季孫之憂不在顓臾而在蕭牆之內也』。", literal: "Now those at left and right do not worry over this yet wish to send troops to repay a hair's breadth of resentment upon distant barbarians—perhaps what Confucius called 'I fear Ji Sun's worry is not in Zhuanyu but within the inner wall.'", idiomatic: "Now those at left and right do not worry over this yet wish to send troops to repay a hair's breadth of resentment upon distant barbarians—perhaps what Confucius called 'I fear Ji Sun's worry is not in Zhuanyu but within the inner wall.'" },
  { zh: "」上從相言，止。", literal: "\" The emperor followed the chancellor's words and stopped.", idiomatic: "\" The emperor followed the chancellor's words and stopped." },
  { zh: "遣長羅侯常惠將張掖、酒泉騎往車師，迎鄭吉及其吏士還渠犁。", literal: "He sent Marquis Changluo Chang Hui to lead Zhangye and Jiuquan cavalry to Cheshi, welcome Zheng Ji and his officials and soldiers back to Queli.", idiomatic: "He sent Marquis Changluo Chang Hui to lead Zhangye and Jiuquan cavalry to Cheshi, welcome Zheng Ji and his officials and soldiers back to Queli." },
  { zh: "召故車師太子軍宿在焉耆者，立以為王；", literal: "He summoned the former Cheshi crown prince Jun, who had lodged at Yanqi, and established him as king;", idiomatic: "He summoned the former Cheshi crown prince Jun, who had lodged at Yanqi, and established him as king;" },
  { zh: "盡徙車師國民令居渠犁，遂以車師故地與匈奴。", literal: "moved all Cheshi state people to dwell at Queli, and thereupon gave Cheshi's former territory to the Xiongnu.", idiomatic: "moved all Cheshi state people to dwell at Queli, and thereupon gave Cheshi's former territory to the Xiongnu." },
  { zh: "以鄭吉為衛司馬，使護善阜善以西南道。", literal: "He made Zheng Ji Guardian Major and had him protect the roads southwest from Shanfu and Shan.", idiomatic: "He made Zheng Ji Guardian Major and had him protect the roads southwest from Shanfu and Shan." },
  { zh: "----6魏相好觀漢故事及便宜章奏，數條漢興已來國家便宜行事及賢臣賈誼、晁錯、董仲舒等所言，奏請施行之。", literal: "----6 Wei Xiang delighted in examining Han precedents and expedient memorials; he repeatedly itemized since Han's rise the state's expedient measures and what worthy ministers Jia Yi, Chao Cuo, Dong Zhongshu, and others had said, memorializing to request their implementation.", idiomatic: "----6 Wei Xiang delighted in examining Han precedents and expedient memorials; he repeatedly itemized since Han's rise the state's expedient measures and what worthy ministers Jia Yi, Chao Cuo, Dong Zhongshu, and others had said, memorializing to request their implementation." },
  { zh: "相敕掾史按事郡國，及休告，從家還至府，輒白四方異聞。", literal: "The chancellor ordered clerks investigating affairs in commanderies and kingdoms that when on leave they returned from home to the office, they should report at once strange news from the four quarters.", idiomatic: "The chancellor ordered clerks investigating affairs in commanderies and kingdoms that when on leave they returned from home to the office, they should report at once strange news from the four quarters." },
  { zh: "或有逆賊、風雨災變，郡不上，相輒奏言之。", literal: "If there were rebels or wind-and-rain disasters and changes that the commandery did not report upward, the chancellor would memorialize them.", idiomatic: "If there were rebels or wind-and-rain disasters and changes that the commandery did not report upward, the chancellor would memorialize them." },
  { zh: "與御史大夫丙吉同心輔政，上皆重之。", literal: "With Censor-in-Chief Bing Ji he assisted government with one heart; the emperor valued them both.", idiomatic: "With Censor-in-Chief Bing Ji he assisted government with one heart; the emperor valued them both." },
  { zh: "丙吉為人深厚，不伐善。", literal: "Bing Ji as a man was deep and thick and did not boast of his goodness.", idiomatic: "Bing Ji as a man was deep and thick and did not boast of his goodness." },
  { zh: "自曾孫遭遇，吉絕口不道前恩，故朝廷莫能明其功也。", literal: "From the imperial great-grandson's encounter with fortune, Ji sealed his mouth and did not speak of former grace—therefore the court could not make clear his merit.", idiomatic: "From the imperial great-grandson's encounter with fortune, Ji sealed his mouth and did not speak of former grace—therefore the court could not make clear his merit." },
  { zh: "會掖庭宮婢則令民夫上書，自陳嘗有阿保之功，章下掖庭令考問，則辭引使者丙吉知狀。", literal: "It happened that a Palace Rear Garden maid named Ze had a commoner husband submit a memorial, himself stating he once had wet-nurse merit; the document went down to the Palace Rear Garden director for examination—Ze in her testimony cited Envoy Bing Ji as knowing the circumstances.", idiomatic: "It happened that a Palace Rear Garden maid named Ze had a commoner husband submit a memorial, himself stating he once had wet-nurse merit; the document went down to the Palace Rear Garden director for examination—Ze in her testimony cited Envoy Bing Ji as knowing the circumstances." },
  { zh: "掖庭令將則詣御史府以視吉，吉識，謂則曰：「汝嘗坐養皇曾孫不謹，督笞汝，汝安得有功！", literal: "The Palace Rear Garden director brought Ze to the Censor's office to show Ji; Ji recognized her and said to Ze: \"You once sat in guilt for nursing the imperial great-grandson without care—I supervised and flogged you—how could you have merit!", idiomatic: "The Palace Rear Garden director brought Ze to the Censor's office to show Ji; Ji recognized her and said to Ze, \"You once sat in guilt for nursing the imperial great-grandson without care—I supervised and flogged you—how could you have merit!" },
  { zh: "獨渭城胡組、淮陽郭徵卿有恩耳。", literal: "Only Weicheng's Hu Zu and Huaiyang's Guo Zhengqing had grace.", idiomatic: "Only Weicheng's Hu Zu and Huaiyang's Guo Zhengqing had grace." },
  { zh: "」分別奏組等共養勞苦狀。", literal: "\" He separately memorialized Zu and the others' joint nursing toil and hardship.", idiomatic: "\" He separately memorialized Zu and the others' joint nursing toil and hardship." },
  { zh: "詔吉求組、徵卿；", literal: "An edict ordered Ji to seek Zu and Zhengqing;", idiomatic: "An edict ordered Ji to seek Zu and Zhengqing;" },
  { zh: "已死，有子孫，皆受厚賞。", literal: "they were already dead; they had descendants—all received generous rewards.", idiomatic: "they were already dead; they had descendants—all received generous rewards." },
  { zh: "詔免則為庶人，賜錢十萬。", literal: "An edict freed Ze to commoner status and bestowed one hundred thousand cash.", idiomatic: "An edict freed Ze to commoner status and bestowed one hundred thousand cash." },
  { zh: "上親見問，然後知吉有舊恩而終不言，上大賢之。", literal: "The emperor personally saw and questioned him; only then did he know Ji had old grace yet to the end did not speak—the emperor greatly esteemed him.", idiomatic: "The emperor personally saw and questioned him; only then did he know Ji had old grace yet to the end did not speak—the emperor greatly esteemed him." },
  { zh: "----7帝以蕭望之經明持重，議論有餘，材任宰相，欲詳試其政事，復以為左馮翊。", literal: "----7 The emperor, because Xiao Wangzhi was clear in the classics, steady and weighty, with discussion to spare and talent fit for chancellor, wished to test his governance in detail and again made him Left Governor of Jingzhao.", idiomatic: "----7 The emperor, because Xiao Wangzhi was clear in the classics, steady and weighty, with discussion to spare and talent fit for chancellor, wished to test his governance in detail and again made him Left Governor of Jingzhao." },
  { zh: "望之從少府出為左遷，恐有不合意，即移病。", literal: "Wangzhi, coming out from Junior Steward as a leftward transfer, feared something did not accord with his wish and at once pleaded illness.", idiomatic: "Wangzhi, coming out from Junior Steward as a leftward transfer, feared something did not accord with his wish and at once pleaded illness." },
  { zh: "上聞之，使侍中成都侯金安上諭意曰：「所用皆更治民以考功。", literal: "The emperor heard it and sent Palace Attendant Marquis Chengdu Jin Anshang to convey the intent: \"Those employed are all rotated to govern the people to examine merit.", idiomatic: "The emperor heard it and sent Palace Attendant Marquis Chengdu Jin Anshang to convey the intent, \"Those employed are all rotated to govern the people to examine merit." },
  { zh: "君前為平原太守日淺，故複試之於三輔，非有所聞也。", literal: "My lord, you formerly were Governor of Pingyuan for few days—therefore you are again tested in the Three Metropolises; it is not that something was heard.", idiomatic: "My lord, you formerly were Governor of Pingyuan for few days—therefore you are again tested in the Three Metropolises; it is not that something was heard." },
  { zh: "」望之即起視事。", literal: "\" Wangzhi at once rose and took up affairs.", idiomatic: "\" Wangzhi at once rose and took up affairs." },
  { zh: "----8初，掖庭令張賀數為弟車騎將軍安世稱皇曾孫之材美及徵怪，安世輒絕止，以為少主在上，不宜稱述曾孫。", literal: "----8 At the beginning, Palace Rear Garden Director Zhang He repeatedly for his younger brother Cavalry General Anshi praised the imperial great-grandson's talent and beauty and portents and marvels; Anshi always cut him off, holding that with the young lord above, one ought not praise and recount the great-grandson.", idiomatic: "----8 At the beginning, Palace Rear Garden Director Zhang He repeatedly for his younger brother Cavalry General Anshi praised the imperial great-grandson's talent and beauty and portents and marvels; Anshi always cut him off, holding that with the young lord above, one ought not praise and recount the great-grandson." },
  { zh: "及帝即位而賀已死，上謂安世曰：「掖庭令平生稱我，將軍止之，是也。", literal: "When the emperor took the throne He was already dead; the emperor said to Anshi: \"The Palace Rear Garden director in his lifetime praised me—the general stopped him; that was right.", idiomatic: "When the emperor took the throne He was already dead; the emperor said to Anshi, \"The Palace Rear Garden director in his lifetime praised me—the general stopped him; that was right." },
  { zh: "」上追思賀恩，欲封其塚為恩德侯，置守塚二百家。", literal: "\" The emperor pursued thought of He's grace and wished to enfeoff his tomb as Marquis of Grace and Virtue and set two hundred households to guard the tomb.", idiomatic: "\" The emperor pursued thought of He's grace and wished to enfeoff his tomb as Marquis of Grace and Virtue and set two hundred households to guard the tomb." },
  { zh: "賀有子蚤死，子安世小男彭祖。", literal: "He had a son who died early; Anshi's youngest son was Pengzu.", idiomatic: "He had a son who died early; Anshi's youngest son was Pengzu." },
  { zh: "彭祖又小與上同席研書指，欲封之，先賜爵關內侯。", literal: "Pengzu was also young and with the emperor shared a mat studying books and pointing—wishing to enfeoff him, he first granted the title Marquis within the Passes.", idiomatic: "Pengzu was also young and with the emperor shared a mat studying books and pointing—wishing to enfeoff him, he first granted the title Marquis within the Passes." },
  { zh: "安世深辭賀封；", literal: "Anshi deeply declined He's enfeoffment;", idiomatic: "Anshi deeply declined He's enfeoffment;" },
  { zh: "又求損守塚戶數，稍減至三十戶。", literal: "he also requested reducing the tomb-guard households, gradually diminished to thirty households.", idiomatic: "he also requested reducing the tomb-guard households, gradually diminished to thirty households." },
  { zh: "上曰：「吾自為掖庭令，非為將軍也。", literal: "The emperor said: \"I do this for the Palace Rear Garden director myself, not for the general.", idiomatic: "The emperor said, \"I do this for the Palace Rear Garden director myself, not for the general." },
  { zh: "」安世乃止，不敢復言。", literal: "\" Anshi thereupon stopped and did not dare speak again.", idiomatic: "\" Anshi thereupon stopped and did not dare speak again." },
  { zh: "----9上心忌故昌邑王賀，賜山陽太守張敞璽書，令謹備盜賊，察往來過客；", literal: "----9 The emperor in his heart was wary of the former King of Changyi He; he bestowed on Governor of Shanyang Zhang Chang a sealed edict, ordering careful guard against bandits and scrutiny of travelers coming and going;", idiomatic: "----9 The emperor in his heart was wary of the former King of Changyi He; he bestowed on Governor of Shanyang Zhang Chang a sealed edict, ordering careful guard against bandits and scrutiny of travelers coming and going;" },
  { zh: "毋下所賜書。", literal: "do not issue downward the bestowed document.", idiomatic: "do not issue downward the bestowed document." },
  { zh: "敞於是條奏賀居處，著其廢亡之效曰：「故昌邑王為人，青黑色，小目，鼻末銳卑，少鬚眉，身體長大，疾痿，行步不便。", literal: "Chang thereupon itemized and memorialized He's dwelling and conduct, setting forth the signs of his deposal and ruin: \"The former King of Changyi as a man was bluish-black in color, small-eyed, nose tip sharp and low, few beard and brows, body tall and large, afflicted with wasting, walking and steps inconvenient.", idiomatic: "Chang thereupon itemized and memorialized He's dwelling and conduct, setting forth the signs of his deposal and ruin: \"The former King of Changyi as a man was bluish-black in color, small-eyed, nose tip sharp and low, few beard and brows, body tall and large, afflicted with wasting, walking and steps inconvenient." },
  { zh: "臣敞嘗與之言，欲動觀其意，即以惡鳥感之曰：『昌邑多梟。", literal: "Your subject Chang once spoke with him, wishing to stir and observe his intent, and thereby with an ill-omen bird moved him, saying: 'Changyi has many owls.", idiomatic: "Your subject Chang once spoke with him, wishing to stir and observe his intent, and thereby with an ill-omen bird moved him, saying: 'Changyi has many owls." },
  { zh: "』故王應曰：『然。", literal: "' The former king replied: 'So.", idiomatic: "' The former king replied, 'So." },
  { zh: "前賀西至長安，殊無梟；", literal: "Before, when He went west to Chang'an, there were especially no owls;", idiomatic: "Before, when He went west to Chang'an, there were especially no owls;" },
  { zh: "復來，東至濟陽，乃復聞梟聲。", literal: "when he came again, going east to Jiyang, he then again heard owl cries.", idiomatic: "when he came again, going east to Jiyang, he then again heard owl cries." },
  { zh: "』察故王衣服、言語、跪起，清狂不惠。", literal: "' Observing the former king's clothes, speech, kneeling and rising—he was clear-mad and not wise.", idiomatic: "' Observing the former king's clothes, speech, kneeling and rising—he was clear-mad and not wise." },
  { zh: "臣敞前言：『哀王歌舞者張脩等十人無子，留守哀王園，請罷歸。", literal: "Your subject Chang earlier said: 'Prince Ai's singers and dancers Zhang Xiu and ten others have no sons; they remain guarding Prince Ai's park—please dismiss and send them home.", idiomatic: "Your subject Chang earlier said, 'Prince Ai's singers and dancers Zhang Xiu and ten others have no sons; they remain guarding Prince Ai's park—please dismiss and send them home." },
  { zh: "』故王聞之曰：『中人守園，疾者當勿治，相殺傷者當勿法，欲令亟死。", literal: "' The former king heard it and said: 'Eunuchs guard the park—when ill they ought not be treated; when they mutually wound and kill they ought not be punished by law—one wishes to make them quickly die.", idiomatic: "' The former king heard it and said, 'Eunuchs guard the park—when ill they ought not be treated; when they mutually wound and kill they ought not be punished by law—one wishes to make them quickly die." },
  { zh: "太守奈何而欲罷之？", literal: "How can the governor wish to dismiss them?", idiomatic: "How can the governor wish to dismiss them?" },
  { zh: "』其天資喜由亂亡，終不見仁義如此。", literal: "' His inborn nature delighted in following disorder to ruin—to the end one does not see benevolence and righteousness like this.", idiomatic: "' His inborn nature delighted in following disorder to ruin—to the end one does not see benevolence and righteousness like this." },
  { zh: "」上乃知賀不足忌也。", literal: "\" The emperor then knew He was not worth fearing.", idiomatic: "\" The emperor then knew He was not worth fearing." },
  { zh: "1春，三月，詔封故昌邑王賀為海昏侯。", literal: "1 Spring, third month—an edict enfeoffed the former King of Changyi He as Marquis of Haihun.", idiomatic: "1 Spring, third month—an edict enfeoffed the former King of Changyi He as Marquis of Haihun." },
  { zh: "----2乙未，詔曰：「朕微眇時，御史大夫丙吉，中郎將史曾、史玄，長樂衛尉許舜，侍中、光祿大夫許延壽，皆與朕有舊恩，及故掖庭令張賀，輔導朕躬，修文學經術，恩惠卓異，厥功茂焉。", literal: "----2 On yiyi, an edict said: \"When We were slight and small, Censor-in-Chief Bing Ji, Gentlemen-of-the-Palace Shi Ceng and Shi Xuan, Chamberlain of Chang Le Guard Xu Shun, Palace Attendant and Household Minister Xu Yanshou—all had old grace with Us; and the former Palace Rear Garden Director Zhang He guided and led Our person, cultivated literary learning and classic arts—grace outstanding and different, their merit luxuriant.", idiomatic: "----2 On yiyi, an edict said, \"When We were slight and small, Censor-in-Chief Bing Ji, Gentlemen-of-the-Palace Shi Ceng and Shi Xuan, Chamberlain of Chang Le Guard Xu Shun, Palace Attendant and Household Minister Xu Yanshou—all had old grace with Us; and the former Palace Rear Garden Director Zhang He guided and led Our person, cultivated literary learning and classic arts—grace outstanding and different, their merit luxuriant." },
  { zh: "《詩》不雲乎：『無德不報』，封賀所子弟子侍中、中郎將彭祖為陽都侯，追賜賀謚曰陽都哀侯，吉為博陽侯，曾為將陵侯，玄為平台侯，舜為博望侯，延壽為樂成侯。", literal: "Does the Odes not say: 'Without virtue there is no requital'? Enfeoff He's son's younger brother's son Palace Attendant and Gentleman-of-the-Palace Pengzu as Marquis of Yangdu; posthumously grant He the posthumous title Marquis Ai of Yangdu; Ji as Marquis of Boyang; Ceng as Marquis of Jiangling; Xuan as Marquis of Pingtai; Shun as Marquis of Bowang; Yanshou as Marquis of Lecheng.", idiomatic: "Does the Odes not say, 'Without virtue there is no requital'? Enfeoff He's son's younger brother's son Palace Attendant and Gentleman-of-the-Palace Pengzu as Marquis of Yangdu; posthumously grant He the posthumous title Marquis Ai of Yangdu; Ji as Marquis of Boyang; Ceng as Marquis of Jiangling; Xuan as Marquis of Pingtai; Shun as Marquis of Bowang; Yanshou as Marquis of Lecheng." },
  { zh: "」賀有孤孫霸，年七歲，拜為散騎、中郎將，賜爵關內侯。", literal: "\" He had a lone grandson Ba, age seven—appointed Attendant Cavalier and Gentleman-of-the-Palace, granted the title Marquis within the Passes.", idiomatic: "\" He had a lone grandson Ba, age seven—appointed Attendant Cavalier and Gentleman-of-the-Palace, granted the title Marquis within the Passes." },
  { zh: "故人下至郡邸獄復作嘗有阿保之功者，皆受官祿、田宅、財物，各以恩深淺報之。", literal: "Old acquaintances down to those in the commandery hostel prison and convict labor who once had wet-nurse merit—all received office salary, fields and houses, goods and wealth, each requited according to the depth or shallowness of grace.", idiomatic: "Old acquaintances down to those in the commandery hostel prison and convict labor who once had wet-nurse merit—all received office salary, fields and houses, goods and wealth, each requited according to the depth or shallowness of grace." },
  { zh: "吉臨當封，病；", literal: "Ji, on the verge of enfeoffment, fell ill;", idiomatic: "Ji, on the verge of enfeoffment, fell ill;" },
  { zh: "上憂其不起，將使人就加印紼而封之，及其生存也。", literal: "the emperor worried he would not rise and was about to send someone to go add the seal cord and enfeoff him while he still lived.", idiomatic: "the emperor worried he would not rise and was about to send someone to go add the seal cord and enfeoff him while he still lived." },
  { zh: "太子太傅夏侯勝曰：「此未死也！", literal: "Crown Prince Grand Tutor Xiahou Sheng said: \"This is not yet death!", idiomatic: "Crown Prince Grand Tutor Xiahou Sheng said, \"This is not yet death!" },
  { zh: "臣聞有陰德者必饗其樂，以及子孫。", literal: "Your subject has heard that one who has hidden virtue must enjoy his blessings, extending to sons and grandsons.", idiomatic: "Your subject has heard that one who has hidden virtue must enjoy his blessings, extending to sons and grandsons." },
  { zh: "今吉未獲報而疾甚，非其死疾也。", literal: "Now Ji has not yet received requital yet his illness is severe—this is not his death-illness.", idiomatic: "Now Ji has not yet received requital yet his illness is severe—this is not his death-illness." },
  { zh: "」後病果愈。", literal: "\" Later his illness indeed recovered.", idiomatic: "\" Later his illness indeed recovered." },
  { zh: "張安世自以父子封侯，在位太盛。", literal: "Zhang Anshi himself, because father and son were enfeoffed as marquises and in office were too flourishing,", idiomatic: "Zhang Anshi himself, because father and son were enfeoffed as marquises and in office were too flourishing," },
  { zh: "乃辭祿，詔都內別藏張氏無名錢以百萬數。", literal: "thereupon resigned salary; an edict had the Metropolitan Treasury separately store Zhang clan unnamed cash in the millions.", idiomatic: "thereupon resigned salary; an edict had the Metropolitan Treasury separately store Zhang clan unnamed cash in the millions." },
  { zh: "安世謹慎周密，每定大政，已決，輒移病出。", literal: "Anshi was careful, cautious, and thorough; whenever great policy was settled and decided, he at once pleaded illness and withdrew.", idiomatic: "Anshi was careful, cautious, and thorough; whenever great policy was settled and decided, he at once pleaded illness and withdrew." },
  { zh: "聞有詔令，乃驚，使吏之丞相府問焉。", literal: "Hearing there was an edict order, he would be startled and send an official to the chancellor's office to inquire.", idiomatic: "Hearing there was an edict order, he would be startled and send an official to the chancellor's office to inquire." },
  { zh: "自朝廷大臣，莫知其與議也。", literal: "From court great ministers on down, none knew he had deliberated.", idiomatic: "From court great ministers on down, none knew he had deliberated." },
  { zh: "嘗有所薦，其人來謝，安世大恨，以為「舉賢達能，豈有私謝邪！", literal: "He once had someone he recommended come to thank him; Anshi greatly resented it, holding that \"recommending the worthy and promoting the able—how could there be private thanks!", idiomatic: "He once had someone he recommended come to thank him; Anshi greatly resented it, holding that \"recommending the worthy and promoting the able—how could there be private thanks!" },
  { zh: "」絕弗復為通。", literal: "\" He cut off and never again allowed contact.", idiomatic: "\" He cut off and never again allowed contact." },
  { zh: "有郎功高不調，自言安世，安世應曰：「君之功高，明主所知，人臣執事，何長短而自言乎！", literal: "There was a Gentleman-of-the-Palace whose merit was high yet he was not transferred; he spoke to Anshi himself; Anshi replied: \"My lord's merit is high—the enlightened lord knows it; a minister holds office—why speak of strengths and weaknesses oneself!", idiomatic: "There was a Gentleman-of-the-Palace whose merit was high yet he was not transferred; he spoke to Anshi himself; Anshi replied, \"My lord's merit is high—the enlightened lord knows it; a minister holds office—why speak of strengths and weaknesses oneself!" },
  { zh: "」絕不許。", literal: "\" He absolutely did not permit it.", idiomatic: "\" He absolutely did not permit it." },
  { zh: "已而郎果遷。", literal: "Before long the Gentleman was indeed transferred.", idiomatic: "Before long the Gentleman was indeed transferred." },
  { zh: "安世自見父子尊顯，懷不自安，為子延壽求出補吏，上以為北地太守；", literal: "Anshi himself saw father and son honored and displayed and in his breast was not at ease; for his son Yanshou he sought to go out and fill an official post—the emperor made him Governor of Beidi;", idiomatic: "Anshi himself saw father and son honored and displayed and in his breast was not at ease; for his son Yanshou he sought to go out and fill an official post—the emperor made him Governor of Beidi;" },
  { zh: "歲餘，上閔安世年老，復徵延壽為左曹、太僕。", literal: "after more than a year the emperor pitied Anshi's old age and again summoned Yanshou as Left Assistant and Grand Coachman.", idiomatic: "after more than a year the emperor pitied Anshi's old age and again summoned Yanshou as Left Assistant and Grand Coachman." },
  { zh: "----3夏，四月，丙子，立皇子欽為淮陽王。", literal: "----3 Summer, fourth month, on bingzi—established the imperial son Qin as King of Huaiyang.", idiomatic: "----3 Summer, fourth month, on bingzi—established the imperial son Qin as King of Huaiyang." },
  { zh: "皇太子年十二，通《論語》、《孝經》。", literal: "The crown prince was twelve years old and had mastered the Analects and Classic of Filial Piety.", idiomatic: "The crown prince was twelve years old and had mastered the Analects and Classic of Filial Piety." },
  { zh: "太傅疏廣謂少傅受曰：「吾聞『知足不辱，知止不殆。", literal: "Grand Tutor Shu Guang said to Junior Tutor Shou: \"I have heard 'Knowing sufficiency brings no disgrace; knowing when to stop brings no peril.", idiomatic: "Grand Tutor Shu Guang said to Junior Tutor Shou, \"I have heard 'Knowing sufficiency brings no disgrace; knowing when to stop brings no peril." },
  { zh: "』今仕宦至二千石，官成名立，如此不去，懼有後悔。", literal: "' Now in office one has reached two thousand dan—office achieved, name established—if at this one does not leave, I fear there will be later regret.", idiomatic: "' Now in office one has reached two thousand dan—office achieved, name established—if at this one does not leave, I fear there will be later regret." },
  { zh: "」即日，父子俱移病，上疏乞骸骨。", literal: "\" That very day, father and son together pleaded illness and submitted a memorial begging their old bones.", idiomatic: "\" That very day, father and son together pleaded illness and submitted a memorial begging their old bones." },
  { zh: "上皆許之，加賜黃金二十斤，皇太子贈以五十斤。", literal: "The emperor approved them both, adding a gift of twenty jin of gold; the crown prince presented fifty jin.", idiomatic: "The emperor approved them both, adding a gift of twenty jin of gold; the crown prince presented fifty jin." },
  { zh: "公卿故人設祖道供張東都門外，送者車數百兩。", literal: "Dukes, ministers, and old friends set out a farewell feast and provisions east of the capital's east gate; those seeing them off numbered several hundred carriages.", idiomatic: "Dukes, ministers, and old friends set out a farewell feast and provisions east of the capital's east gate; those seeing them off numbered several hundred carriages." },
  { zh: "道路觀者皆曰：「賢哉二大夫！", literal: "Roadside onlookers all said: \"How worthy, the two great officers!", idiomatic: "Roadside onlookers all said, \"How worthy, the two great officers!" },
  { zh: "」或歎息為之下泣。", literal: "\" Some sighed and wept for them.", idiomatic: "\" Some sighed and wept for them." },
  { zh: "廣、受歸鄉里，日令其家賣金共具，請族人、故舊、賓客，與相娛樂。", literal: "Guang and Shou returned to their native village; day by day they had their households sell gold to supply provisions together, invited clansmen, old friends, and guests, and mutually enjoyed themselves.", idiomatic: "Guang and Shou returned to their native village; day by day they had their households sell gold to supply provisions, invited clansmen, old friends, and guests, and enjoyed themselves together." },
  { zh: "或勸廣以其金為子孫頗立產業者，廣曰：「吾豈老悖不念子孫哉！", literal: "Some urged Guang to use his gold to establish some estate for his sons and grandsons; Guang said: \"How could I in old age be perverse and not think of sons and grandsons!", idiomatic: "Some urged Guang to use his gold to establish some estate for his sons and grandsons; Guang said, \"How could I in old age be perverse and not think of sons and grandsons!" },
  { zh: "顧自有舊田廬，令子孫勤力其中，足以共衣食，與凡人齊。", literal: "Only that I already have old fields and cottages—let sons and grandsons work diligently therein; it suffices to share food and clothing and be level with ordinary people.", idiomatic: "Only that I already have old fields and cottages—let sons and grandsons work diligently therein; it suffices to share food and clothing and be level with ordinary people." },
  { zh: "今復增益之以為贏餘，但教子孫怠墮耳。", literal: "Now again to increase and add to it as surplus profit only teaches sons and grandsons idleness and decay.", idiomatic: "Now again to increase and add to it as surplus profit only teaches sons and grandsons idleness and decay." },
  { zh: "賢而多財，則損其志；", literal: "If worthy yet with much wealth, then their will is harmed;", idiomatic: "If worthy yet with much wealth, then their will is harmed;" },
  { zh: "愚而多財，則益其過。", literal: "if foolish yet with much wealth, then their faults are increased.", idiomatic: "if foolish yet with much wealth, then their faults are increased." },
  { zh: "且夫富者眾之怨也，吾既無以教化子孫，不欲益其過而生怨。", literal: "Moreover the wealthy are the multitude's resentment; I already have no means to transform and teach sons and grandsons—I do not wish to increase their faults and engender resentment.", idiomatic: "Moreover the wealthy are the multitude's resentment; I already have no means to transform and teach sons and grandsons—I do not wish to increase their faults and engender resentment." },
  { zh: "又此金者，聖主所以惠養老臣也，故樂與鄉黨、宗族共饗其賜，以盡吾餘日，不亦可乎！", literal: "Again, this gold is what the sage lord uses to favor and nourish an old minister—therefore I delight to share his gift with village and neighborhood and clan kin, to exhaust my remaining days—is that not acceptable!", idiomatic: "Again, this gold is what the sage lord uses to favor and nourish an old minister—therefore I delight to share his gift with village and neighborhood and clan kin, to exhaust my remaining days—is that not acceptable!" },
  { zh: "」於是族人悅服。", literal: "\" Thereupon the clansmen were pleased and submitted.", idiomatic: "\" Thereupon the clansmen were pleased and submitted." },
  { zh: "----4穎川太守黃霸使郵亭、鄉官皆畜雞、豚，以贍鰥、寡、貧、窮者；", literal: "----4 Governor of Yingchuan Huang Ba had postal stations and village officers all raise chickens and pigs to support widowers, widows, the poor, and the destitute;", idiomatic: "----4 Governor of Yingchuan Huang Ba had postal stations and village officers all raise chickens and pigs to support widowers, widows, the poor, and the destitute;" },
  { zh: "然後為條教，置父老、師帥、伍長，班行之於民間，勸以為善防奸之意，及務耕桑、節用、殖財、種樹、畜養，去浮淫之費。", literal: "then established regulations and instructions, set up village elders, company leaders, and squad chiefs, and distributed them among the people, urging the intent of doing good and guarding against wickedness, and to devote themselves to farming and sericulture, economize use, increase wealth, plant trees, and raise livestock, removing extravagant and dissolute expenses.", idiomatic: "then established regulations and instructions, set up village elders, company leaders, and squad chiefs, and distributed them among the people, urging the intent of doing good and guarding against wickedness, and to devote themselves to farming and sericulture, economize use, increase wealth, plant trees, and raise livestock, removing extravagant and dissolute expenses." },
  { zh: "其治，米鹽靡密，初若煩碎，然霸精力能推行之。", literal: "His governance was fine as rice and salt, minute and dense—at first it seemed troublesome and trivial, yet Ba with full energy could carry it out.", idiomatic: "His governance was fine as rice and salt, minute and dense—at first it seemed troublesome and trivial, yet Ba with full energy could carry it out." },
  { zh: "吏民見者，語次尋繹，問他陰伏以相參考，聰明識事，吏民不知所出，咸稱神明，豪厘不敢有所欺。", literal: "Officials and people who met him—in the course of conversation he traced and followed, asked other hidden matters to cross-reference; perceptive and knowing affairs—officials and people did not know whence it came; all called him divine, and not a hair's breadth dared any deception.", idiomatic: "Officials and people who met him—in the course of conversation he traced and followed, asked other hidden matters to cross-reference; perceptive and knowing affairs—officials and people did not know whence it came; all called him divine, and not a hair's breadth dared any deception." },
  { zh: "奸人去入它郡，盜賊日少。", literal: "Wicked men left and entered other commanderies; bandits daily grew fewer.", idiomatic: "Wicked men left and entered other commanderies; bandits daily grew fewer." },
  { zh: "霸力行教化而後誅罰，務在成就全安長吏。", literal: "Ba strongly practiced transformation and teaching and afterward punishments, striving to complete and fully secure long-serving officials.", idiomatic: "Ba strongly practiced transformation and teaching and afterward punishments, striving to complete and fully secure long-serving officials." },
  { zh: "許丞老，病聾，督郵白欲逐之。", literal: "Assistant Magistrate Xu was old, afflicted with deafness; the supervising clerk reported wishing to expel him.", idiomatic: "Assistant Magistrate Xu was old, afflicted with deafness; the supervising clerk reported wishing to expel him." },
  { zh: "霸曰：「許丞廉吏，雖老，尚能拜起送迎，正頗重聽何傷！", literal: "Ba said: \"Assistant Magistrate Xu is an incorrupt official; though old, he can still bow, rise, and see off and welcome—what harm if he is rather hard of hearing!", idiomatic: "Ba said, \"Assistant Magistrate Xu is an incorrupt official; though old, he can still bow, rise, and see off and welcome—what harm if he is rather hard of hearing!" },
  { zh: "且善助之，毋失賢者意！", literal: "Moreover, assist him well—do not lose the worthy man's intent!", idiomatic: "Moreover, assist him well—do not lose the worthy man's intent!" },
  { zh: "」或問其故，霸曰：「數易長吏，送故迎新之費，及奸吏因緣，絕簿書，盜財物，公私費耗甚多，皆當出於民。", literal: "\" Someone asked the reason; Ba said: \"Frequently changing long officials—the expenses of seeing off the old and welcoming the new, and wicked clerks seizing opportunity, cutting off registers and documents, stealing goods and wealth—public and private costs and waste are very many; all must come from the people.", idiomatic: "\" Someone asked the reason; Ba said, \"Frequently changing long officials—the expenses of seeing off the old and welcoming the new, and wicked clerks seizing opportunity, cutting off registers and documents, stealing goods and wealth—public and private costs and waste are very many; all must come from the people." },
  { zh: "所易新吏又未必賢，或不如其故，徒相益為亂。", literal: "The newly changed officials are again not necessarily worthy—perhaps not equal to the former; they only mutually increase disorder.", idiomatic: "The newly changed officials are again not necessarily worthy—perhaps not equal to the former; they only mutually increase disorder." },
  { zh: "凡治道，去其泰甚者耳。", literal: "As for the Way of governance, one only removes what is too excessive.", idiomatic: "As for the Way of governance, one only removes what is too excessive." },
  { zh: "」霸以外寬內明，得吏民心，戶口歲增，治為天下第一，徵守京兆尹。", literal: "\" Ba, outwardly lenient and inwardly clear, won officials' and people's hearts; registered households increased year by year; his governance was rated first under Heaven—summoned to guard as Governor of Jingzhao.", idiomatic: "\" Ba, outwardly lenient and inwardly clear, won officials' and people's hearts; registered households increased year by year; his governance was rated first under Heaven—summoned to guard as Governor of Jingzhao." },
  { zh: "頃之，坐法，連貶秩；", literal: "Shortly thereafter, he sat in guilt of law and was repeatedly demoted in rank;", idiomatic: "Shortly thereafter, he sat in guilt of law and was repeatedly demoted in rank;" },
  { zh: "有詔復歸穎川為太守，以八百石居。", literal: "an edict returned him to Yingchuan as governor, dwelling at eight hundred dan.", idiomatic: "an edict returned him to Yingchuan as governor, dwelling at eight hundred dan." },
  { zh: "1春，正月，詔：「年八十以上，非誣告、殺傷人，他皆勿坐。", literal: "1 Spring, first month—an edict: \"For those eighty years and above, except false accusation and killing or wounding people, for all else do not sit in judgment.", idiomatic: "1 Spring, first month—an edict: \"For those eighty years and above, except false accusation and killing or wounding people, for all else do not sit in judgment." },
  { zh: "」----2右扶風尹翁歸卒，家無餘財。", literal: "\" ----2 Yin Wengui, Governor of Right Fufeng, died; his household had no surplus wealth.", idiomatic: "\" ----2 Yin Wengui, Governor of Right Fufeng, died; his household had no surplus wealth." },
  { zh: "秋，八月，詔曰：「翁歸廉平鄉正，治民異等。", literal: "Autumn, eighth month—an edict said: \"Wengui was incorrupt, level, and village-upright; governing the people was of a different grade.", idiomatic: "Autumn, eighth month—an edict said, \"Wengui was incorrupt, level, and village-upright; governing the people was of a different grade." },
  { zh: "其賜翁歸子黃金百斤，以奉祭祀。", literal: "Let his son be granted one hundred jin of gold to support sacrificial rites.", idiomatic: "Let his son be granted one hundred jin of gold to support sacrificial rites." },
  { zh: "」----3上令有司求高祖功臣子孫失侯者，得槐裡公乘周廣漢等百三十六人，皆賜黃金二十斤，復其家，令奉祭祀，世世勿絕。", literal: "\" ----3 The emperor ordered the relevant offices to seek descendants of Gaozu's meritorious ministers who had lost their marquisates; they obtained Zhou Guanghan of Huaili, rank Gongcheng, and one hundred thirty-six persons—all were granted twenty jin of gold, restored their households, and ordered to maintain sacrificial rites, generation after generation never to cease.", idiomatic: "\" ----3 The emperor ordered the relevant offices to seek descendants of Gaozu's meritorious ministers who had lost their marquisates; they obtained Zhou Guanghan of Huaili, rank Gongcheng, and one hundred thirty-six persons—all were granted twenty jin of gold, restored their households, and ordered to maintain sacrificial rites, generation after generation never to cease." },
  { zh: "----4丙寅，富平敬侯張安世薨。", literal: "----4 On bingyin, Marquis Jing of Fuping Zhang Anshi passed away.", idiomatic: "----4 On bingyin, Marquis Jing of Fuping Zhang Anshi passed away." },
  { zh: "----5初，扶陽節侯韋賢薨，長子弘有罪繫獄，家人矯賢令，以次子大河都尉玄成為後。", literal: "----5 At the beginning, Marquis Jie of Fuyang Wei Xian passed away; the eldest son Hong had guilt and was bound in prison; the family forged Xian's order and made the second son, Metropolitan Commandant of the Great River Wei Xuancheng, the heir.", idiomatic: "----5 At the beginning, Marquis Jie of Fuyang Wei Xian passed away; the eldest son Hong had guilt and was bound in prison; the family forged Xian's order and made the second son, Metropolitan Commandant of the Great River Wei Xuancheng, the heir." },
  { zh: "玄成深知其非賢雅意，即陽為病狂，臥便利，妄笑語，昏亂。", literal: "Xuancheng deeply knew this was not Xian's refined intent; he at once openly feigned mad illness, lay in the privy, spoke wild laughter and talk, and was muddled and confused.", idiomatic: "Xuancheng deeply knew this was not Xian's refined intent; he at once openly feigned mad illness, lay in the privy, spoke wild laughter and talk, and was muddled and confused." },
  { zh: "既葬，當襲爵，以狂不應召。", literal: "After the burial, when he should have inherited the title, because of madness he did not respond to summons.", idiomatic: "After the burial, when he should have inherited the title, because of madness he did not respond to summons." },
  { zh: "大鴻臚奏狀，章下丞相、御史案驗。", literal: "Grand Herald memorialized the circumstances; the document went down to Chancellor and Censor for investigation and verification.", idiomatic: "Grand Herald memorialized the circumstances; the document went down to Chancellor and Censor for investigation and verification." },
  { zh: "案事丞相史乃與玄成書曰：「古之辭讓，必有文義可觀，故能垂榮於後。", literal: "The investigating Chancellor's clerk then wrote Xuancheng a letter saying: \"Ancient declinations and yieldings must have literary meaning worth viewing—therefore they could hang glory upon later generations.", idiomatic: "The investigating Chancellor's clerk then wrote Xuancheng a letter saying, \"Ancient declinations and yieldings must have literary meaning worth viewing—therefore they could hang glory upon later generations." },
  { zh: "今子獨壞容貌，蒙恥辱為狂癡，光曜晻而不宣，微哉子之所托名也！", literal: "Now my lord alone ruins his countenance, bears disgrace as mad and foolish—brilliance dim and not displayed; how slight is the name my lord trusts to!", idiomatic: "Now my lord alone ruins his countenance, bears disgrace as mad and foolish—brilliance dim and not displayed; how slight is the name my lord trusts to!" },
  { zh: "僕素愚陋，過為宰相執事，願少聞風聲；", literal: "Your servant is by nature foolish and crude, in excess serving as the chancellor's agent—your servant wishes to hear a little of the wind and sound;", idiomatic: "Your servant is by nature foolish and crude, in excess serving as the chancellor's agent—your servant wishes to hear a little of the wind and sound;" },
  { zh: "不然，恐子傷高而僕為小人也。", literal: "if not, I fear my lord will harm his loftiness and your servant become a petty man.", idiomatic: "if not, I fear my lord will harm his loftiness and your servant become a petty man." },
  { zh: "」玄成友人侍郎章亦上疏言：「聖王貴以禮讓為國，宜優養玄成，勿枉其志，使得自安衡門之下。", literal: "\" Xuancheng's friend Gentleman-in-Attendance Zhang also submitted a memorial saying: \"The sage king esteems taking ritual yielding as the state—it is fitting to favor and nourish Xuancheng, not to bend his will, so that he may secure himself beneath a plain gate.", idiomatic: "\" Xuancheng's friend Gentleman-in-Attendance Zhang also submitted a memorial saying, \"The sage king esteems taking ritual yielding as the state—it is fitting to favor and nourish Xuancheng, not to bend his will, so that he may secure himself beneath a plain gate." },
  { zh: "」而丞相、御史遂以玄成實不病，劾奏之，有詔勿劾，引拜；", literal: "\" But Chancellor and Censor thereupon held that Xuancheng was in fact not ill, impeached and memorialized him; an edict ordered do not impeach—summon and invest;", idiomatic: "\" But Chancellor and Censor thereupon held that Xuancheng was in fact not ill, impeached and memorialized him; an edict ordered do not impeach—summon and invest;" },
  { zh: "玄成不得已，受爵。", literal: "Xuancheng had no alternative and accepted the title.", idiomatic: "Xuancheng had no alternative and accepted the title." },
  { zh: "帝高其節，以玄成為河南太守。", literal: "The emperor esteemed his integrity and made Xuancheng Governor of Henan.", idiomatic: "The emperor esteemed his integrity and made Xuancheng Governor of Henan." },
  { zh: "----6車師王烏貴之走烏孫也，烏孫留不遣。", literal: "----6 When the King of Cheshi Wugui fled to the Wusun, the Wusun detained him and did not send him away.", idiomatic: "----6 When the King of Cheshi Wugui fled to the Wusun, the Wusun detained him and did not send him away." },
  { zh: "漢遣使責烏孫，烏孫送烏貴詣闕。", literal: "The Han sent envoys to reproach the Wusun; the Wusun sent Wugui to the palace gate.", idiomatic: "The Han sent envoys to reproach the Wusun; the Wusun sent Wugui to the palace gate." },
  { zh: "----7初，武帝開河西四郡，隔絕羌與匈奴相通之路，斥逐諸羌。", literal: "----7 At the beginning, Emperor Wu opened the four commanderies west of the Yellow River, cut off the Qiang from the Xiongnu's connecting road, and expelled the various Qiang.", idiomatic: "----7 At the beginning, Emperor Wu opened the four commanderies west of the Yellow River, cut off the Qiang from the Xiongnu's connecting road, and expelled the various Qiang." },
  { zh: "不使居湟中地。", literal: "He did not let them dwell in the Huangzhong lands.", idiomatic: "He did not let them dwell in the Huangzhong lands." },
  { zh: "及帝即位，光祿大夫義渠安國使行諸羌；", literal: "When the emperor took the throne, Household Minister Yiqu Anguo was sent to tour the various Qiang;", idiomatic: "When the emperor took the throne, Household Minister Yiqu Anguo was sent to tour the various Qiang;" },
  { zh: "先零豪言：「願時度湟水北，逐民所不田處畜牧。", literal: "the Xianling chieftain said: \"We wish from time to time to cross north of the Huang River, following where the people do not farm to pasture livestock.", idiomatic: "the Xianling chieftain said, \"We wish from time to time to cross north of the Huang River, following where the people do not farm to pasture livestock." },
  { zh: "」安國以聞。", literal: "\" Anguo reported it upward.", idiomatic: "\" Anguo reported it upward." },
  { zh: "後將軍趙充國劾安國奉使不敬。", literal: "Rear General Zhao Chongguo impeached Anguo for disrespect on his mission.", idiomatic: "Rear General Zhao Chongguo impeached Anguo for disrespect on his mission." },
  { zh: "是後羌人旁緣前言，抵冒度湟水，郡縣不能禁。", literal: "After this the Qiang people, edging along the former words, pressed and crossed the Huang River; commanderies and counties could not forbid it.", idiomatic: "After this the Qiang people, edging along the former words, pressed and crossed the Huang River; commanderies and counties could not forbid it." },
  { zh: "既而先零與諸羌種豪二百餘人解仇、交質、盟詛。", literal: "Before long the Xianling and more than two hundred chieftains of various Qiang tribes dissolved enmity, exchanged hostages, and swore alliance curses.", idiomatic: "Before long the Xianling and more than two hundred chieftains of various Qiang tribes dissolved enmity, exchanged hostages, and swore alliance curses." },
  { zh: "上聞之，以問趙充國，對曰：「羌人所以易制者，以其種自有豪，數相攻擊，勢不壹也。", literal: "The emperor heard it and questioned Zhao Chongguo; he replied: \"The reason the Qiang are easy to control is that among their tribes each has its own chieftains—they repeatedly attack one another and their power is not one.", idiomatic: "The emperor heard it and questioned Zhao Chongguo; he replied, \"The reason the Qiang are easy to control is that among their tribes each has its own chieftains—they repeatedly attack one another and their power is not one." },
  { zh: "往三十餘歲西羌反時，亦先解仇合約攻令居，與漢相距，五六年乃定。", literal: "More than thirty years ago when the Western Qiang rebelled, they also first dissolved enmity and joined in covenant to attack Lingju, faced off with the Han, and only after five or six years was it settled.", idiomatic: "More than thirty years ago when the Western Qiang rebelled, they also first dissolved enmity and joined in covenant to attack Lingju, faced off with the Han, and only after five or six years was it settled." },
  { zh: "匈奴數誘羌人，欲與之共擊張掖、酒泉地，使羌居之。", literal: "The Xiongnu repeatedly enticed the Qiang, wishing to join with them to strike Zhangye and Jiuquan territory and have the Qiang dwell there.", idiomatic: "The Xiongnu repeatedly enticed the Qiang, wishing to join with them to strike Zhangye and Jiuquan territory and have the Qiang dwell there." },
  { zh: "間者匈奴困於西方，疑其更遣使至羌中與相結。", literal: "Recently the Xiongnu have been distressed in the west—your subject suspects they again sent envoys into the Qiang lands to join with them.", idiomatic: "Recently the Xiongnu have been distressed in the west—your subject suspects they again sent envoys into the Qiang lands to join with them." },
  { zh: "臣恐羌變未止此，且復結聯他種，宜及未然為之備。", literal: "Your subject fears the Qiang change will not stop here but will again link with other tribes—it is fitting, while it has not yet happened, to prepare against it.", idiomatic: "Your subject fears the Qiang change will not stop here but will again link with other tribes—it is fitting, while it has not yet happened, to prepare against it." },
  { zh: "」後月餘，羌侯狼何果遣使至匈奴藉兵，欲擊鄯善、敦煌以絕漢道。", literal: "\" More than a month later, Qiang Marquis Langhe indeed sent envoys to the Xiongnu to borrow troops, wishing to strike Shanshan and Dunhuang and cut off the Han road.", idiomatic: "\" More than a month later, Qiang Marquis Langhe indeed sent envoys to the Xiongnu to borrow troops, wishing to strike Shanshan and Dunhuang and cut off the Han road." },
  { zh: "充國以為「狼何勢不能獨造此計，疑匈奴使已至羌中，先零、罕、幵乃解仇作約。", literal: "Chongguo held that \"Langhe by his power could not alone devise this plan—your subject suspects Xiongnu envoys had already reached the Qiang lands, and the Xianling, Han, and Jian thereupon dissolved enmity and made covenant.", idiomatic: "Chongguo held that \"Langhe by his power could not alone devise this plan—your subject suspects Xiongnu envoys had already reached the Qiang lands, and the Xianling, Han, and Jian thereupon dissolved enmity and made covenant." },
  { zh: "到秋馬肥，變必起矣。", literal: "When autumn comes and horses are fat, the change will surely arise.", idiomatic: "When autumn comes and horses are fat, the change will surely arise." },
  { zh: "宜遣使者行邊兵，豫為備敕，視諸羌毋令解仇，以發覺其謀。", literal: "It is fitting to send envoys to tour border troops, prepare instructions in advance, watch the various Qiang and not let them dissolve enmity, so as to discover their plot.", idiomatic: "It is fitting to send envoys to tour border troops, prepare instructions in advance, watch the various Qiang and not let them dissolve enmity, so as to discover their plot." },
  { zh: "」於是兩府復白遣義渠安國行視諸羌，分別善惡。", literal: "\" Thereupon the Two Offices again reported white, sending Yiqu Anguo to tour and inspect the various Qiang, distinguishing good from bad.", idiomatic: "\" Thereupon the Two Offices again reported white, sending Yiqu Anguo to tour and inspect the various Qiang, distinguishing good from bad." },
  { zh: "----8是時，比年豐稔，穀石五錢。", literal: "----8 At this time, year after year was abundant harvest; grain was five cash per picul.", idiomatic: "----8 At this time, year after year was abundant harvest; grain was five cash per picul." },
  { zh: "----category:資治通鑑", literal: "----category: Zizhi Tongjian", idiomatic: "----category: Zizhi Tongjian" }
];
